struct PluginManagerOperationOutcome {
    message: String,
    reload_languages: bool,
    restart_plugins: bool,
}

async fn apply_plugin_manager_operation(
    manager: &plugin::package::PluginPackageManager,
    operation: &str,
) -> anyhow::Result<PluginManagerOperationOutcome> {
    let (verb, raw_id) = operation
        .split_once('\t')
        .ok_or_else(|| anyhow::anyhow!("invalid plugin operation"))?;
    let id = plugin::package::PluginId::parse(raw_id)?;
    match verb {
        "enable" => {
            let installed = manager
                .installed(&id)?
                .ok_or_else(|| anyhow::anyhow!("plugin `{id}` is not installed"))?;
            manager.set_enabled(&id, true)?;
            Ok(PluginManagerOperationOutcome {
                message: format!("Enabled plugin {id}."),
                reload_languages: installed.has_languages,
                restart_plugins: installed.has_husk || installed.has_companion,
            })
        }
        "disable" => {
            let installed = manager
                .installed(&id)?
                .ok_or_else(|| anyhow::anyhow!("plugin `{id}` is not installed"))?;
            manager.set_enabled(&id, false)?;
            Ok(PluginManagerOperationOutcome {
                message: format!("Disabled plugin {id}."),
                reload_languages: installed.has_languages,
                restart_plugins: installed.has_husk || installed.has_companion,
            })
        }
        "update" => {
            let installed = manager.update(&id).await?;
            Ok(PluginManagerOperationOutcome {
                message: if installed.has_native_grammars {
                    format!(
                        "Updated {} to {}. Approve its current native grammars before loading them.",
                        installed.name, installed.version
                    )
                } else {
                    format!("Updated {} to {}.", installed.name, installed.version)
                },
                reload_languages: installed.has_languages && !installed.has_native_grammars,
                restart_plugins: installed.has_husk || installed.has_companion,
            })
        }
        "remove" => {
            let installed = manager
                .installed(&id)?
                .ok_or_else(|| anyhow::anyhow!("plugin `{id}` is not installed"))?;
            manager.remove(&id, false)?;
            Ok(PluginManagerOperationOutcome {
                message: format!("Removed plugin {id}; its private data was preserved."),
                reload_languages: installed.has_languages,
                restart_plugins: installed.has_husk || installed.has_companion,
            })
        }
        _ => anyhow::bail!("unknown plugin operation `{verb}`"),
    }
}

fn plugin_manager_items(
    installed: &[plugin::package::InstalledPlugin],
    catalog: &BTreeMap<plugin::package::PluginId, plugin::catalog::CatalogPackage>,
    catalog_url: &str,
) -> Vec<PickerItem> {
    let installed_by_id = installed
        .iter()
        .map(|package| (&package.id, package))
        .collect::<BTreeMap<_, _>>();
    let mut installed_catalog_items = Vec::new();
    let mut installed_custom_items = Vec::new();
    let mut available_items = Vec::new();
    let mut unavailable_items = Vec::new();

    for package in catalog.values() {
        let installed_at_id = installed_by_id.get(&package.id).copied();
        let installed = installed_at_id
            .filter(|installed| installed_from_catalog(installed, catalog_url, &package.id));
        let custom_install = installed_at_id
            .filter(|installed| !installed_from_catalog(installed, catalog_url, &package.id));
        let requirements = package
            .requirements
            .iter()
            .flat_map(|requirement| [&requirement.command, &requirement.purpose])
            .cloned()
            .collect::<Vec<_>>();
        let (lifecycle, compact_annotation) = match (installed, custom_install) {
            (Some(installed), _) if installed.version < package.version => (
                format!(
                    "{} · v{} → v{}",
                    package.tier.label(),
                    installed.version,
                    package.version
                ),
                format!("v{} → v{}", installed.version, package.version),
            ),
            (Some(installed), _) => (
                format!(
                    "{} · v{} · Installed",
                    package.tier.label(),
                    installed.version
                ),
                format!("v{}", installed.version),
            ),
            (None, Some(custom)) => (
                format!(
                    "{} · v{} · Custom v{} installed",
                    package.tier.label(),
                    package.version,
                    custom.version
                ),
                format!("v{}", package.version),
            ),
            (None, None) => (
                format!("{} · v{}", package.tier.label(), package.version),
                format!("v{}", package.version),
            ),
        };
        let (availability, unavailable_message) = catalog_package_availability(package);
        let (annotation, compact_annotation) = unavailable_message
            .as_ref()
            .map_or((lifecycle, compact_annotation), |_| {
                (availability.clone(), availability)
            });
        let item = PickerItem {
            id: installed.map_or_else(
                || {
                    let prefix = if unavailable_message.is_some() {
                        "unavailable"
                    } else {
                        "catalog"
                    };
                    format!("{prefix}:{}", package.id)
                },
                |_| format!("installed:{}", package.id),
            ),
            icon: None,
            label: package.name.clone(),
            kind: Some(if unavailable_message.is_some() {
                "Warning".to_string()
            } else {
                "Language".to_string()
            }),
            annotation: Some(annotation),
            detail: None,
            data: json!({
                "package": package.id.as_str(),
                "search_terms": [
                    package.id.as_str(),
                    package.description.as_str(),
                    package.languages.join(" "),
                    package.repository.as_str(),
                    package.source_path.to_string_lossy(),
                    requirements.join(" "),
                    package.tier.label(),
                ],
                "annotation_align": "right",
                "annotation_right_margin": 2,
                "compact_annotation": compact_annotation,
            }),
            matches: Vec::new(),
            detail_matches: Vec::new(),
            preview: None,
        };
        if installed.is_some() {
            installed_catalog_items.push(item);
        } else if unavailable_message.is_some() {
            unavailable_items.push(item);
        } else {
            available_items.push(item);
        }
    }

    for package in installed {
        if catalog.contains_key(&package.id)
            && installed_from_catalog(package, catalog_url, &package.id)
        {
            continue;
        }
        let catalog_source = matches!(
            &package.source,
            plugin::package::PluginInstallSource::Catalog {
                catalog_url: source_catalog_url,
                ..
            } if source_catalog_url == catalog_url
        );
        installed_custom_items.push(PickerItem {
            id: format!("installed:{}", package.id),
            icon: None,
            label: package.name.clone(),
            kind: Some("Language".to_string()),
            annotation: Some(format!(
                "{} · v{} · {}",
                if catalog_source {
                    "Installed"
                } else {
                    "Custom"
                },
                package.version,
                if package.enabled {
                    "Enabled"
                } else {
                    "Disabled"
                }
            )),
            detail: None,
            data: json!({
                "package": package.id.as_str(),
                "search_terms": [
                    package.id.as_str(),
                    package.languages.join(" "),
                    if catalog_source { "catalog official" } else { "custom source" },
                ],
                "annotation_align": "right",
                "annotation_right_margin": 2,
                "compact_annotation": format!("v{}", package.version),
            }),
            matches: Vec::new(),
            detail_matches: Vec::new(),
            preview: None,
        });
    }

    let mut items = Vec::new();
    items.extend(installed_catalog_items);
    items.extend(installed_custom_items);
    items.extend(available_items);
    items.extend(unavailable_items);
    items.push(PickerItem {
        id: "custom-source".to_string(),
        icon: None,
        label: "+ Add custom source…".to_string(),
        kind: Some("Add".to_string()),
        annotation: None,
        detail: None,
        data: json!({
            "search_terms": [
                "custom source github repository owner repo ref local path development checkout",
            ],
        }),
        matches: Vec::new(),
        detail_matches: Vec::new(),
        preview: None,
    });
    items
}

fn plugin_manager_filter_score(item: &PickerItem, query: &str) -> Option<i64> {
    let matcher = SkimMatcherV2::default();
    query.split_whitespace().try_fold(0, |total, token| {
        let label_score = plugin_manager_field_score(&matcher, &item.label, token, 5_000);
        let annotation_score = item
            .annotation
            .as_deref()
            .and_then(|value| plugin_manager_field_score(&matcher, value, token, 4_000));
        let metadata_score = item
            .data
            .get("search_terms")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(Value::as_str)
            .filter_map(|value| plugin_manager_field_score(&matcher, value, token, 3_000))
            .max();
        Some(
            total
                + label_score
                    .into_iter()
                    .chain(annotation_score)
                    .chain(metadata_score)
                    .max()?,
        )
    })
}

fn plugin_manager_field_score(
    matcher: &SkimMatcherV2,
    field: &str,
    token: &str,
    weight: i64,
) -> Option<i64> {
    let field_lower = field.to_ascii_lowercase();
    let token_lower = token.to_ascii_lowercase();
    let exact_bonus = if field.eq_ignore_ascii_case(token) {
        2_000
    } else if field_lower.starts_with(&token_lower) {
        1_000
    } else if field_lower.contains(&token_lower) {
        500
    } else {
        0
    };
    matcher
        .fuzzy_match(field, token)
        .map(|score| weight + exact_bonus + score)
}

fn language_pack_picker(
    editor: &Editor,
    items: Vec<PickerItem>,
    status: impl Into<String>,
    busy: bool,
) -> Picker {
    Picker::builder()
        .title("Language packs")
        .structured_items(items)
        .id(PLUGIN_MANAGER_PICKER_ID)
        .placeholder("Search language packs")
        .status(status)
        .busy(busy)
        .filter_action(plugin_manager_filter_score)
        .content_sized(88, 14)
        .fit_content_width(56)
        .status_on_query_line()
        .select_action(Action::PluginManagerSelect)
        .build(editor)
}

fn catalog_package_action_status(package: &plugin::catalog::CatalogPackage) -> String {
    let missing = package
        .requirements
        .iter()
        .filter(|requirement| !command_available(&requirement.command))
        .map(|requirement| {
            format!(
                "{} {}",
                requirement.command,
                if requirement.optional {
                    "optional"
                } else {
                    "required"
                }
            )
        })
        .collect::<Vec<_>>();
    let readiness = if missing.is_empty() {
        "Tools ready".to_string()
    } else {
        format!("Missing {}", missing.join(", "))
    };
    format!(
        "{} · v{} · {} · {readiness}",
        package.tier.label(),
        package.version,
        package.languages.join(", ")
    )
}

fn plugin_manager_action_item(
    id: String,
    label: impl Into<String>,
    annotation: impl Into<String>,
    kind: &str,
) -> PickerItem {
    PickerItem {
        id,
        icon: None,
        label: label.into(),
        kind: Some(kind.to_string()),
        annotation: Some(annotation.into()),
        detail: None,
        data: Value::Null,
        matches: Vec::new(),
        detail_matches: Vec::new(),
        preview: None,
    }
}

fn native_grammar_consent_message(
    package: &plugin::catalog::CatalogPackage,
) -> anyhow::Result<String> {
    let artifact = package
        .artifact(crate::language::host_target())
        .ok_or_else(|| {
            anyhow::anyhow!(
                "language pack `{}` is unavailable for `{}`",
                package.id,
                crate::language::host_target()
            )
        })?;
    let digests = artifact
        .grammars
        .iter()
        .map(|(language, digest)| format!("{language}: {digest}"))
        .collect::<Vec<_>>()
        .join("\n");
    Ok(format!(
        "Native Tree-sitter grammars execute inside Red.\n\nPackage: {} v{}\nSource: {} @ {}\n\nVerified SHA-256:\n{}\n\nApproval is limited to these exact catalog-verified bytes.",
        package.name,
        package.version,
        package.repository,
        package.resolved_commit,
        digests
    ))
}

fn installed_grammar_consent_message(
    package: &plugin::package::InstalledPlugin,
    digests: &BTreeMap<String, String>,
) -> anyhow::Result<String> {
    anyhow::ensure!(
        !digests.is_empty(),
        "language pack `{}` has no native grammars to approve",
        package.id
    );
    let source = match &package.source {
        plugin::package::PluginInstallSource::Path { path } => {
            format!("Local path: {}", path.display())
        }
        plugin::package::PluginInstallSource::GitHub {
            repository,
            requested_version,
        } => format!(
            "GitHub: {repository}@{}",
            requested_version.as_deref().unwrap_or("default branch")
        ),
        plugin::package::PluginInstallSource::Catalog {
            catalog_url,
            resolved_commit,
            ..
        } => format!("Catalog: {catalog_url}\nResolved commit: {resolved_commit}"),
    };
    let digests = digests
        .iter()
        .map(|(language, digest)| format!("{language}: {digest}"))
        .collect::<Vec<_>>()
        .join("\n");
    Ok(format!(
        "Native Tree-sitter grammars execute inside Red.\n\nPackage: {} v{}\n{}\n\nCurrent SHA-256:\n{}\n\nApproval is limited to these exact installed bytes. If they change before approval, Red will stop.",
        package.name, package.version, source, digests
    ))
}

fn catalog_package_availability(
    package: &plugin::catalog::CatalogPackage,
) -> (String, Option<String>) {
    if !package
        .supports_current_red_release()
        .expect("supported Red API versions are valid SemVer")
    {
        return (
            format!("Requires Red API {}", package.red_api),
            Some(format!(
                "Language pack `{}` requires Red API `{}`, which this Red release does not support.",
                package.id, package.red_api
            )),
        );
    }

    let host_target = crate::language::host_target();
    if package.artifact(host_target).is_none() {
        return (
            "Unavailable on this platform".to_string(),
            Some(format!(
                "Language pack `{}` is unavailable for `{host_target}`.",
                package.id
            )),
        );
    }

    (package.tier.label().to_string(), None)
}

fn confirmed_catalog_install_action(
    catalog_url: &str,
    package: &plugin::catalog::CatalogPackage,
    trust_native_grammars: bool,
) -> Action {
    Action::PluginManagerCatalogInstall {
        catalog_url: catalog_url.to_string(),
        package: Box::new(package.clone()),
        trust_native_grammars,
    }
}

fn installed_from_catalog(
    installed: &plugin::package::InstalledPlugin,
    catalog_url: &str,
    package_id: &plugin::package::PluginId,
) -> bool {
    matches!(
        &installed.source,
        plugin::package::PluginInstallSource::Catalog {
            catalog_url: source_catalog_url,
            package,
            ..
        } if source_catalog_url == catalog_url && package == package_id
    )
}

fn command_available(command: &str) -> bool {
    let Some(path) = std::env::var_os("PATH") else {
        return false;
    };
    std::env::split_paths(&path).any(|directory| {
        let candidate = directory.join(command);
        if candidate.is_file() {
            return true;
        }
        #[cfg(windows)]
        {
            ["exe", "cmd", "bat"]
                .iter()
                .any(|extension| candidate.with_extension(extension).is_file())
        }
        #[cfg(not(windows))]
        false
    })
}
const MACRO_MAX_REPLAY_DEPTH: usize = 20;
const MACRO_MAX_REPLAY_EVENTS: usize = 10_000;
const MIN_EDITOR_WINDOW_WIDTH: usize = 10;
const MIN_EDITOR_WINDOW_HEIGHT: usize = 7;
const MIN_DOCKED_PANEL_WIDTH: usize = 12;
const MIN_DOCKED_PANEL_HEIGHT: usize = 4;
const SESSION_SNAPSHOT_WARNING: &str =
    "Crash recovery is not being saved; check free space and permissions or reduce open-buffer size";

fn normalize_terminal_paste(text: &str) -> String {
    text.replace("\r\n", "\n").replace('\r', "\n")
}

/// Command lines, searches, and pickers are single-line inputs. Keep a pasted
/// newline from accidentally accepting or executing their current contents.
fn pasted_input_line(text: &str) -> String {
    normalize_terminal_paste(text)
        .split('\n')
        .next()
        .unwrap_or_default()
        .to_string()
}

fn normalize_macro_register(register: char) -> Option<char> {
    (register.is_ascii_alphanumeric()).then(|| register.to_ascii_lowercase())
}

fn single_macro_token_character(token: &str) -> anyhow::Result<char> {
    let mut characters = token.chars();
    let character = characters
        .next()
        .ok_or_else(|| anyhow::anyhow!("macro modifier is missing a key"))?;
    anyhow::ensure!(
        characters.next().is_none(),
        "macro modifier must contain exactly one key"
    );
    Ok(character)
}

fn text_position_for_char_index(text: &str, char_index: usize) -> TextPosition {
    let mut line = 0;
    let mut character = 0;
    for value in text.chars().take(char_index) {
        if value == '\n' {
            line += 1;
            character = 0;
        } else {
            character += 1;
        }
    }
    TextPosition::new(line, character)
}

fn parse_substitute_segment(input: &str, delimiter: char) -> anyhow::Result<(String, &str)> {
    let mut value = String::new();
    let mut escaped = false;
    for (offset, character) in input.char_indices() {
        if escaped {
            if character != delimiter {
                value.push('\\');
            }
            value.push(character);
            escaped = false;
            continue;
        }
        if character == '\\' {
            escaped = true;
            continue;
        }
        if character == delimiter {
            let next = offset + character.len_utf8();
            return Ok((value, &input[next..]));
        }
        value.push(character);
    }
    anyhow::bail!("substitute is missing a closing {delimiter}")
}

fn decode_substitute_replacement(input: &str) -> String {
    let mut decoded = String::with_capacity(input.len());
    let mut characters = input.chars();
    while let Some(character) = characters.next() {
        if character != '\\' {
            decoded.push(character);
            continue;
        }

        match characters.next() {
            Some('r') => decoded.push('\n'),
            Some('\\') => decoded.push('\\'),
            Some(character) => {
                decoded.push('\\');
                decoded.push(character);
            }
            None => decoded.push('\\'),
        }
    }
    decoded
}

fn substitute_replacement_with_line_ending<'a>(
    replacement: &'a str,
    line_ending: &str,
) -> Cow<'a, str> {
    if line_ending == "\n" || !replacement.contains('\n') {
        Cow::Borrowed(replacement)
    } else {
        Cow::Owned(replacement.replace('\n', line_ending))
    }
}

