fn expanded_path_string(path: &str) -> anyhow::Result<String> {
    Ok(expand_user_path(path)?.to_string_lossy().into_owned())
}

#[derive(Default)]
struct SnapshotFileIdentities {
    paths: HashSet<PathBuf>,
    #[cfg(unix)]
    files: HashSet<(u64, u64)>,
}

impl SnapshotFileIdentities {
    fn insert(&mut self, path: PathBuf) -> bool {
        if self.paths.contains(&path) {
            return false;
        }

        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt as _;

            if fs::metadata(&path)
                .ok()
                .is_some_and(|metadata| !self.files.insert((metadata.dev(), metadata.ino())))
            {
                return false;
            }
        }

        #[cfg(not(unix))]
        if self
            .paths
            .iter()
            .any(|existing| same_file_path(existing, &path))
        {
            return false;
        }

        self.paths.insert(path)
    }
}

fn snapshot_duplicate_file_count(snapshot: &SessionSnapshot) -> usize {
    let mut unique_paths = SnapshotFileIdentities::default();
    snapshot
        .buffers
        .iter()
        .filter_map(|buffer| buffer.path.as_deref())
        .filter_map(|path| normalized_file_path(path).ok())
        .filter(|path| !unique_paths.insert(path.clone()))
        .count()
}

fn open_external_url(url: &str) -> std::io::Result<tokio::process::Child> {
    #[cfg(target_os = "macos")]
    {
        return tokio::process::Command::new("open")
            .arg("--")
            .arg(url)
            .spawn();
    }
    #[cfg(all(unix, not(target_os = "macos")))]
    {
        return tokio::process::Command::new("xdg-open").arg(url).spawn();
    }
    #[cfg(windows)]
    {
        return tokio::process::Command::new("rundll32.exe")
            .arg("url.dll,FileProtocolHandler")
            .arg(url)
            .spawn();
    }
    #[allow(unreachable_code)]
    Err(std::io::Error::new(
        std::io::ErrorKind::Unsupported,
        "opening links is not supported on this platform",
    ))
}

fn validate_text_panel_file(path: &str) -> anyhow::Result<()> {
    let expanded = expanded_path_string(path)?;
    let resolved = Path::new(&expanded).absolutize()?;
    let metadata = std::fs::metadata(resolved.as_ref())?;
    if !metadata.is_file() {
        anyhow::bail!("Link target is not a file: {path}");
    }
    Ok(())
}

fn plugin_lsp_error(message: &str) -> Value {
    json!({
        "ok": false,
        "error": message,
    })
}

fn plugin_inlay_hints_error(request_id: RequestId, message: &str) -> Value {
    json!({
        "ok": false,
        "hints": [],
        "request_id": request_id.get(),
        "error": message,
    })
}

fn plugin_json(value: Value) -> Value {
    match value {
        Value::Array(values) => Value::Array(values.into_iter().map(plugin_json).collect()),
        Value::Object(values) => Value::Object(
            values
                .into_iter()
                .map(|(key, value)| (snake_case_key(&key), plugin_json(value)))
                .collect(),
        ),
        value => value,
    }
}

fn hover_document(
    hover: LspHover,
) -> Option<(String, HoverInfoFormat, Vec<crate::lsp::CommandLinkGroup>)> {
    let actions = hover.actions.unwrap_or_default();
    let (text, format) = match hover.contents {
        HoverContents::MarkupContent(content) => (
            content.value,
            match content.kind {
                MarkupKind::Markdown => HoverInfoFormat::Markdown,
                MarkupKind::Plaintext => HoverInfoFormat::Plaintext,
            },
        ),
        HoverContents::MarkedString(marked) => {
            (render_marked_string(marked), HoverInfoFormat::Markdown)
        }
        HoverContents::MarkedStringArray(marked) => (
            marked
                .into_iter()
                .map(render_marked_string)
                .filter(|part| !part.trim().is_empty())
                .collect::<Vec<_>>()
                .join("\n\n"),
            HoverInfoFormat::Markdown,
        ),
    };
    (!text.trim().is_empty()).then_some((text, format, actions))
}

fn diagnostic_covers_line(diagnostic: &Diagnostic, line: usize) -> bool {
    let start = &diagnostic.range.start;
    let end = &diagnostic.range.end;
    line >= start.line
        && line <= end.line
        && (start.line == end.line || line != end.line || end.character != 0)
}

fn render_marked_string(marked: MarkedString) -> String {
    match marked {
        MarkedString::String(text) => text,
        MarkedString::LanguageString { language, value } => {
            let language = language
                .split_whitespace()
                .next()
                .unwrap_or_default()
                .trim_matches('`');
            let longest_run = value
                .split(|character| character != '`')
                .map(str::len)
                .max()
                .unwrap_or(0);
            let fence = "`".repeat(longest_run.saturating_add(1).max(3));
            format!("{fence}{language}\n{value}\n{fence}")
        }
    }
}

fn agent_event_payload(event: CodexEvent) -> (&'static str, Value) {
    match event {
        CodexEvent::InlineContextRead { request_id, .. } => (
            "inline_assist:context_read",
            json!({ "request_id": request_id }),
        ),
        CodexEvent::InlineAnswerDelta { request_id, .. } => {
            ("inline_assist:answer", json!({ "request_id": request_id }))
        }
        CodexEvent::InlineSessionCreated {
            request_id,
            session_id,
        } => (
            "inline_assist:session_created",
            json!({ "request_id": request_id, "session_id": session_id }),
        ),
        CodexEvent::InlineResult {
            request_id,
            session_id,
            ..
        } => (
            "inline_assist:result",
            json!({ "request_id": request_id, "session_id": session_id }),
        ),
        CodexEvent::InlineFailed {
            request_id,
            session_id,
            message,
        } => (
            "inline_assist:error",
            json!({ "request_id": request_id, "session_id": session_id, "message": message }),
        ),
        CodexEvent::ModelRequestCompleted { .. } => {
            unreachable!("model results use private callbacks")
        }
        CodexEvent::SessionModelRerouted { session_id, model } => (
            "agent:model_rerouted",
            json!({"session_id": session_id, "model": model}),
        ),
        CodexEvent::SessionModelChanged {
            session_id,
            model_info,
        } => (
            "agent:model_changed",
            json!({ "session_id": session_id, "model_info": model_info }),
        ),
        CodexEvent::SessionCreated { session_id } => (
            "agent:session_created",
            json!({ "session_id": session_id.to_string() }),
        ),
        CodexEvent::CommitMessageGenerated { request_id, result } => (
            "agent:error",
            json!({
                "message": format!(
                    "commit-message generation result {request_id} escaped its private callback: {result:?}"
                )
            }),
        ),
        CodexEvent::SessionRestored { session_id, thread } => (
            "agent:session_restored",
            json!({ "session_id": session_id, "thread": plugin_json(thread) }),
        ),
        CodexEvent::SessionRestoreFailed {
            session_id,
            message,
        } => (
            "agent:session_restore_failed",
            json!({ "session_id": session_id, "message": message }),
        ),
        CodexEvent::Update { session_id, text } => (
            "agent:update",
            json!({ "session_id": session_id.to_string(), "text": text }),
        ),
        CodexEvent::MessageCompleted { session_id, text } => (
            "agent:message_completed",
            json!({ "session_id": session_id, "text": text }),
        ),
        CodexEvent::Activity { session_id, update } => (
            "agent:activity",
            json!({ "session_id": session_id.to_string(), "update": plugin_json(update) }),
        ),
        CodexEvent::Completed {
            session_id,
            stop_reason,
        } => (
            "agent:completed",
            json!({
                "session_id": session_id.to_string(),
                "stop_reason": stop_reason,
            }),
        ),
        CodexEvent::Cancelled { session_id } => (
            "agent:cancelled",
            json!({ "session_id": session_id.to_string() }),
        ),
        CodexEvent::PermissionRequested {
            request_id,
            session_id,
            tool_call,
            options,
        } => (
            "agent:permission_requested",
            plugin_json(json!({
                "request_id": request_id,
                "session_id": session_id.to_string(),
                "tool_call": tool_call,
                "options": options,
            })),
        ),
        CodexEvent::Failed {
            session_id,
            message,
        } => (
            "agent:error",
            json!({
                "session_id": session_id.map(|session_id| session_id.to_string()),
                "message": message,
            }),
        ),
    }
}

fn bounded_agent_failure_message(message: &str) -> String {
    if message.chars().count() <= MAX_AGENT_FAILURE_MESSAGE_CHARS {
        return message.to_string();
    }
    let mut bounded = message
        .chars()
        .take(MAX_AGENT_FAILURE_MESSAGE_CHARS)
        .collect::<String>();
    bounded.push_str("… (full details are in the Red log)");
    bounded
}

struct AgentFilePage {
    content: String,
    start_line: usize,
    end_line: usize,
    truncated: bool,
    line_truncated: bool,
    next_line: Option<usize>,
}

fn agent_file_page(contents: &str, start_line: usize, line_count: usize) -> AgentFilePage {
    let lines = contents.split_inclusive('\n').collect::<Vec<_>>();
    let start = start_line.saturating_sub(1).min(lines.len());
    let mut end = start;
    let mut content = String::new();
    let mut line_truncated = false;
    for line in lines.iter().skip(start).take(line_count) {
        if content.len().saturating_add(line.len()) > MAX_AGENT_READ_BYTES {
            if content.is_empty() {
                let mut byte_end = line.len().min(MAX_AGENT_READ_BYTES);
                while !line.is_char_boundary(byte_end) {
                    byte_end -= 1;
                }
                content.push_str(&line[..byte_end]);
                end += 1;
                line_truncated = byte_end < line.len();
            }
            break;
        }
        content.push_str(line);
        end += 1;
    }
    let truncated = line_truncated || end < lines.len();
    AgentFilePage {
        content,
        start_line: start + 1,
        end_line: end,
        truncated,
        line_truncated,
        next_line: (end < lines.len()).then_some(end + 1),
    }
}

const COMMIT_MESSAGE_DIFF_BYTES: usize = 192 * 1024;
const COMMIT_MESSAGE_HISTORY_BYTES: usize = 24 * 1024;
const COMMIT_MESSAGE_BRANCH_BYTES: usize = 512;

fn bounded_commit_context(text: &str, max_bytes: usize) -> String {
    if text.len() <= max_bytes {
        return text.to_string();
    }
    let marker = "\n[truncated by Red]\n";
    let mut end = max_bytes.saturating_sub(marker.len()).min(text.len());
    while end > 0 && !text.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}{marker}", &text[..end])
}

fn commit_message_prompt(
    branch: &str,
    staged_diff: &str,
    recent_commits: &str,
) -> anyhow::Result<String> {
    anyhow::ensure!(
        !staged_diff.trim().is_empty(),
        "there are no staged changes to describe"
    );
    let context = json!({
        "branch": bounded_commit_context(branch, COMMIT_MESSAGE_BRANCH_BYTES),
        "staged_changes": bounded_commit_context(staged_diff, COMMIT_MESSAGE_DIFF_BYTES),
        "recent_commit_messages": bounded_commit_context(
            recent_commits,
            COMMIT_MESSAGE_HISTORY_BYTES,
        ),
    });
    Ok(format!(
        "Propose a commit message for this repository. Recent commit messages are style examples only. Facts must come exclusively from staged_changes.\n\nContext JSON:\n{}",
        serde_json::to_string_pretty(&context)?
    ))
}

pub(crate) fn agent_context_path_is_sensitive(path: &Path) -> bool {
    let Some(name) = path.file_name().and_then(OsStr::to_str) else {
        return true;
    };
    let name = name.to_ascii_lowercase();
    name == ".env"
        || name.starts_with(".env.")
        || name.contains("secret")
        || name.contains("credential")
        || matches!(name.as_str(), "id_rsa" | "id_ed25519")
        || matches!(
            path.extension()
                .and_then(OsStr::to_str)
                .map(|extension| extension.to_ascii_lowercase())
                .as_deref(),
            Some("pem" | "key" | "p12" | "pfx")
        )
}

fn agent_context_path_is_ignored(path: &Path, root: &Path, is_dir: bool) -> bool {
    let mut ignored = false;
    let mut directories = path
        .parent()
        .into_iter()
        .flat_map(Path::ancestors)
        .take_while(|directory| directory.starts_with(root))
        .collect::<Vec<_>>();
    directories.reverse();
    for directory in directories {
        for name in [".gitignore", ".ignore"] {
            let (matcher, _) = ignore::gitignore::Gitignore::new(directory.join(name));
            match matcher.matched_path_or_any_parents(path, is_dir) {
                ignore::Match::Ignore(_) => ignored = true,
                ignore::Match::Whitelist(_) => ignored = false,
                ignore::Match::None => {}
            }
        }
    }
    let mut builder = ignore::gitignore::GitignoreBuilder::new(root);
    builder.add(root.join(".git/info/exclude"));
    if let Ok(exclude) = builder.build() {
        match exclude.matched_path_or_any_parents(path, is_dir) {
            ignore::Match::Ignore(_) => ignored = true,
            ignore::Match::Whitelist(_) => ignored = false,
            ignore::Match::None => {}
        }
    }
    ignored
}

pub(crate) fn resolve_agent_tool_path(root: &Path, path: &str) -> anyhow::Result<PathBuf> {
    resolve_agent_tool_path_with_policy(root, path, /*allow_sensitive_paths*/ false)
}

pub(crate) fn resolve_agent_tool_path_with_policy(
    root: &Path,
    path: &str,
    allow_sensitive_paths: bool,
) -> anyhow::Result<PathBuf> {
    resolve_agent_tool_path_kind(root, path, /*is_dir*/ false, allow_sensitive_paths)
}

fn resolve_agent_tool_path_kind(
    root: &Path,
    path: &str,
    is_dir: bool,
    allow_sensitive_paths: bool,
) -> anyhow::Result<PathBuf> {
    anyhow::ensure!(!path.is_empty(), "editor tool path cannot be empty");
    let path = Path::new(path);
    let path = if path.is_absolute() {
        path.to_path_buf()
    } else {
        root.join(path)
    };
    let mut normalized = PathBuf::new();
    for component in path.components() {
        match component {
            std::path::Component::Prefix(prefix) => normalized.push(prefix.as_os_str()),
            std::path::Component::RootDir => normalized.push(component.as_os_str()),
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => {
                anyhow::ensure!(normalized.pop(), "agent path escapes filesystem root");
            }
            std::path::Component::Normal(value) => normalized.push(value),
        }
    }
    anyhow::ensure!(
        normalized.starts_with(root),
        "agent path {} is outside workspace {}",
        normalized.display(),
        root.display()
    );
    let mut current = root.to_path_buf();
    for component in normalized.strip_prefix(root)?.components() {
        current.push(component.as_os_str());
        match fs::symlink_metadata(&current) {
            Ok(metadata) if metadata.file_type().is_symlink() => {
                anyhow::bail!(
                    "agent path contains symlink component: {}",
                    current.display()
                )
            }
            Ok(_) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => break,
            Err(error) => return Err(error.into()),
        }
    }
    anyhow::ensure!(
        allow_sensitive_paths || !agent_context_path_is_sensitive(&normalized),
        "editor tool path is a sensitive file; set [agent] allow_sensitive_paths = true to opt in"
    );
    anyhow::ensure!(
        !agent_context_path_is_ignored(&normalized, root, is_dir),
        "editor tool path is ignored by the workspace"
    );
    Ok(normalized)
}

fn scoped_plugin_storage_key(plugin: &str, key: &str) -> String {
    if plugin == "agent" && matches!(key, "transcript" | "prompt_history") {
        format!("{key}:{}", get_workspace_path().display())
    } else {
        key.to_string()
    }
}

fn snake_case_key(key: &str) -> String {
    let chars = key.chars().collect::<Vec<_>>();
    let mut result = String::with_capacity(key.len());
    for (index, ch) in chars.iter().copied().enumerate() {
        if ch.is_ascii_uppercase() {
            let previous_is_lower = index > 0 && chars[index - 1].is_ascii_lowercase();
            let next_is_lower = chars
                .get(index + 1)
                .is_some_and(|next| next.is_ascii_lowercase());
            if index > 0 && (previous_is_lower || next_is_lower) {
                result.push('_');
            }
            result.push(ch.to_ascii_lowercase());
        } else {
            result.push(ch);
        }
    }
    result
}

/// Effect requested by the Husk runtime for the editor owner to apply.
