/// Single-task owner of Red's interactive application state.
///
/// The editor coordinates buffers, windows, rendering, LSP, plugins,
/// persistence, and live agent edits. External tasks communicate through
/// messages; they do not mutate this state directly.
pub struct Editor {
    /// Domain sub-controller managing open buffers and tab selection.
    buffer_manager: buffer_manager::BufferManager,

    /// Plugin-owned scratch buffers and the commands that finish their workflows.
    scratch_buffers: HashMap<BufferId, ScratchBufferCommands>,

    /// Domain sub-controller managing session recovery and snapshots
    session_manager: session_manager::SessionManager,

    /// Domain sub-controller coordinating LSP document state and notifications
    lsp_coordinator: lsp_coordinator::LspCoordinator,

    /// Domain sub-controller managing background AI agent state and tool channels
    agent_manager: agent_manager::AgentManager,

    /// One editor-owned bounded inline edit, including stale-response guards.
    inline_assist: Option<InlineAssistSession>,
    /// Hidden jobs remain addressable independently of the foreground dialog.
    inline_jobs: BTreeMap<String, inline_jobs::ParkedInlineAssist>,
    inline_activity_animation: inline_jobs::InlineActivityAnimation,
    inline_completion_notice: inline_notifications::InlineCompletionNoticeState,
    staged_inline_agent_handoff: Option<inline_agent_outcomes::StagedHandoff>,

    /// Session-local annotations; never serialized into source or text undo history.
    inline_comments: Vec<inline_comments::InlineComment>,
    inline_comment_selections: HashMap<(WindowId, BufferId), uuid::Uuid>,
    inline_history: InlineHistory,
    inline_history_browser: Option<inline_history::HistoryBrowser>,

    /// LSP client for code intelligence features
    lsp: Box<dyn LspClient>,

    /// Editor configuration settings
    config: Config,

    /// Recoverable configuration problems retained until explicitly acknowledged.
    config_diagnostics: Vec<ConfigDiagnostic>,
    config_diagnostics_acknowledged: bool,
    /// Original configuration source and strict overrides reused by explicit language reloads.
    language_config_path: PathBuf,
    language_config_overrides: Vec<String>,

    /// Visual theme settings
    pub theme: Theme,

    /// Short-lived Git metadata used by configurable status-line sections.
    statusline_git_cache: StatuslineGitCache,

    /// Plugin system registry
    plugin_registry: PluginRegistry,

    /// Last successfully fetched curated package catalog used by the manager picker.
    plugin_catalog: BTreeMap<plugin::package::PluginId, plugin::catalog::CatalogPackage>,
    plugin_catalog_url: String,

    /// Lazily spawned native companions owned by installed plugins.
    companion_manager: Arc<tokio::sync::Mutex<plugin::companion::CompanionManager>>,

    /// Syntax highlighting engine
    highlighter: Highlighter,

    /// Full-document structural queries, independent from viewport highlighting.
    syntax_textobjects: SyntaxTextObjectService,
    syntax_indentation: crate::syntax_indent::SyntaxIndentation,

    /// Cached syntax highlight spans per buffer for the most recently parsed
    /// viewport-plus-margin slice.
    highlight_cache: HashMap<usize, ViewportHighlightEntry>,

    /// Delimiter partners indexed only after the cursor lands on a configured bracket.
    bracket_match_cache: Option<matchit::BracketMatchCache>,

    /// Memoized display layout, shared by the many per-frame layout queries.
    layout_cache: std::cell::RefCell<HashMap<LayoutCacheKey, std::sync::Arc<DisplayLayout>>>,

    /// Window manager handling splits and layout
    window_manager: WindowManager,

    /// Terminal output handle
    stdout: std::io::BufWriter<TerminalOutput>,

    /// Keyboard mode owned by this interactive terminal, never by the detached core.
    keyboard_protocol: crate::keyboard::KeyboardProtocol,

    /// Whether this editor still owns terminal modes that need restoring.
    terminal_active: bool,

    /// Whether render operations should write terminal escape sequences
    terminal_output_enabled: bool,

    /// Final terminal cursor command queued since the last flush.
    #[cfg(test)]
    pending_terminal_cursor: Option<TerminalCursorState>,

    /// Final terminal cursor state observed at the last flush boundary.
    #[cfg(test)]
    flushed_terminal_cursor: Option<TerminalCursorState>,

    /// Number of terminal flushes observed by cursor synchronization tests.
    #[cfg(test)]
    terminal_flush_generation: u64,

    #[cfg(test)]
    full_render_count: u64,

    /// Whether the terminal window currently has focus.
    is_focused: bool,

    /// Suppresses the mouse-down used to reactivate the terminal while a
    /// non-editor surface already owns logical focus.
    suppress_reactivation_click: bool,

    /// Incremented after full renders so event handling can avoid duplicate frames.
    render_generation: u64,

    /// Picker callbacks may enqueue navigation that must commit before the next input event.
    service_background_before_next_input: bool,

    /// Rows changed by the most recent detached frame, reused for protocol deltas.
    last_detached_changed_rows: Vec<usize>,

    /// Active window represented by the last committed frame.
    last_rendered_window: Option<WindowId>,

    /// Viewport represented by the committed cells, not the latest logical motion.
    last_rendered_viewport: Option<RenderedViewport>,

    /// True once the startup splash has been drawn at least once.
    splash_shown: bool,

    /// Latched when the splash's visibility conditions first fail after it was
    /// shown, so it never reappears within the session.
    splash_dismissed: bool,

    /// The last frame sent to the terminal. Keeping this separately lets the
    /// renderer diff frames without cloning the entire render buffer.
    previous_render_buffer: Option<RenderBuffer>,

    /// Forces the next full frame to repaint cells whose unresolved styles are
    /// unchanged but whose theme-derived colors have changed.
    force_full_redraw: bool,

    /// Last terminal cursor cell painted into the render buffer.
    last_rendered_cursor_position: Option<(usize, usize)>,

    /// Terminal rows containing the previously rendered matching delimiter pair.
    last_rendered_bracket_rows: Vec<usize>,

    /// Last rendered surface under the terminal-owned cursor.
    ///
    /// Insert mode and input components use the terminal cursor rather than
    /// the synthetic block cursor, so OSC cursor colors must be repaired
    /// against the actual cell they are drawn over.
    last_rendered_cursor_surface: Option<Style>,

    /// Suppresses per-step repainting while queued repeated motions are drained.
    defer_motion_render: bool,

    /// Nested synthetic/local edit publication boundary.
    edit_batch: edit_batch::EditBatch,

    /// Repaint scope accumulated by deferred navigation.
    deferred_motion_render: MotionRender,

    /// Earliest state before a repeated-motion batch and the latest cause.
    /// The final snapshot is read when the batch flushes, so state events are
    /// delivered once with the final cursor/viewport position.
    deferred_plugin_event: Option<(EditorEventSnapshot, String)>,

    /// Nesting depth for visual-block replay. Replay edits should update the
    /// buffer and current transaction without repainting or notifying per row.
    block_replay_depth: usize,

    /// Whether a buffer change notification was deferred during block replay.
    block_replay_change_deferred: bool,

    /// Terminal size (width, height)
    size: (u16, u16),

    /// Top line of viewport (for vertical scrolling)
    vtop: usize,

    /// Left column of viewport (for horizontal scrolling)
    vleft: usize,

    /// First skipped display column for wrapped long-line scrolling.
    skipcol: usize,

    /// Whether the active window wraps long lines.
    wrap: bool,

    /// Cursor x position (column)
    cx: usize,

    /// Cursor y position (line)
    cy: usize,

    /// Display-column goal used when moving vertically.
    cursor_goal: CursorGoal,

    /// Previous cursor y position (for line highlighting)
    prev_highlight_y: Option<usize>,

    /// Visual x position (includes gutter width)
    vx: usize,

    /// Current editor mode (normal, insert, visual, etc)
    mode: Mode,

    /// Ctrl-N selections scoped to one stable buffer/window/revision owner.
    multi_cursor: Option<multi_cursor::MultiCursorSession>,

    /// Captured dividers moved by directional keys while pane resize mode is active.
    pane_resize_mode: Option<PaneResizeMode>,

    /// Temporary presentation of one live window or docked pane.
    zoomed_pane: Option<FocusTarget>,

    /// Cursor position where the current insert session began.
    insert_entry_cursor: Option<CursorSnapshot>,

    /// Whitespace created by auto-indent that is still removable as a blank line.
    generated_indent: Option<GeneratedIndent>,

    /// Partial command being entered
    waiting_command: Option<String>,

    /// Next key action to process
    waiting_key_action: Option<KeyAction>,

    /// Fully entered configured-keymap prefix, such as `Space h`.
    keymap_hint_prefix: Vec<String>,

    /// Time at which the delayed prefix guide becomes visible.
    keymap_hint_deadline: Option<Instant>,

    /// Whether the delayed prefix guide is currently visible.
    keymap_hints_visible: bool,

    /// Actions that are pending while in visual mode
    pending_select_action: Option<ActionOnSelection>,

    /// Partially entered visual-mode text object, such as `i` in `viw`.
    pending_visual_text_object_scope: Option<TextObjectScope>,

    /// Partially entered normal-mode Vim operator, such as `d` in `diw`.
    pending_operator: Option<PendingOperator>,

    /// Partially entered character motion, such as f or F followed by a target.
    pending_character_motion: Option<PendingCharacterMotion>,

    /// Last completed character search, used by the reverse-repeat binding.
    last_character_motion: Option<(ForwardCharacterMotion, char)>,

    /// Whether Normal-mode `r` is waiting for its replacement character.
    pending_replace: bool,

    /// Executed actions
    actions: Vec<Action>,

    /// Input recipe for the last completed content-changing command.
    ///
    /// Unlike macros, this is scoped to one semantic change and is finalized only when
    /// the edit transaction returns to a stable Normal-mode boundary.
    last_semantic_change: Option<SemanticChange>,
    pending_semantic_change: Option<PendingSemanticChange>,
    replaying_semantic_change: bool,

    /// Vim-style macro state. Register contents are stored as editable key notation;
    /// `events` is only the in-progress recording.
    pending_macro_action: Option<PendingMacroAction>,
    macro_recording: Option<MacroRecording>,
    last_played_macro: Option<char>,
    macro_replay_depth: usize,
    macro_instructions_remaining: usize,
    macro_replay_queue: VecDeque<MacroReplayEvent>,

    /// Buffer-local, file-global, and special Vim marks. Anchors use flat Unicode
    /// character coordinates and are transformed at the canonical edit boundary.
    pending_mark_action: Option<PendingMarkAction>,
    local_marks: HashMap<BufferId, HashMap<char, EditAnchor>>,
    global_marks: HashMap<char, EditAnchor>,
    special_marks: HashMap<(BufferId, char), EditAnchor>,
    last_visual_selections: HashMap<BufferId, LastVisualSelection>,
    substitute_confirmation: Option<SubstituteConfirmation>,

    /// Current command line content
    command: String,

    /// Persistent preferences, including command-line history.
    preferences: PreferencesStore,

    /// Owns the protected practice buffer and original window layout.
    learn_session: Option<learning::LearnSession>,

    /// A release has changed, but no visible client has seen its announcement yet.
    whats_new_startup_pending: bool,

    /// Set only after an interactive terminal or authenticated detached client exists.
    whats_new_auto_presentation_enabled: bool,

    /// The announcement was prepared and still needs a successful rendered-frame claim.
    whats_new_needs_persistence: bool,

    /// First launch is presented only after a visible, usable editor is ready.
    welcome_startup_pending: bool,

    /// Owns the unnamed practice buffer while a nonmodal guided tour is active.
    tutorial_controller: Option<TutorialController>,

    /// Active command-history navigation state.
    command_history_navigation: Option<PromptHistoryNavigation>,

    /// Active command-line completion state.
    command_completion: Option<CommandCompletionState>,

    /// Current search term
    search_term: String,

    /// Direction of the most recently committed search.
    search_direction: SearchDirection,

    /// Interactive search state while editing / or ?.
    active_search: Option<SearchSession>,

    /// Matches for the most recently rendered or previewed search.
    search_match_cache: Option<SearchMatchCache>,

    /// Bounded prior queries reused when an incremental search is edited.
    search_match_history: VecDeque<SearchMatchCache>,

    /// Whether persistent hlsearch rendering has been cleared with :noh.
    search_highlights_suppressed: bool,

    /// Session-local notification records, independent of the legacy display slot.
    notifications: NotificationCenter,
    message_browser: Option<notifications::MessageBrowser>,
    notification_presentation: notifications::NotificationPresentation,
    notification_frame_candidate: Option<notifications::NotificationExposureKey>,
    notification_exposure: Option<notifications::NotificationExposure>,
    notification_client_attached: bool,
    notification_animation_start: Instant,
    notification_fallback: Option<String>,
    config_notification: Option<NotificationId>,
    session_notification: Option<NotificationId>,
    persistent_notification_messages: [Option<String>; 2],

    /// Compatibility display slot while existing producers are migrated.
    last_error: Option<String>,

    /// Active dialog/popup component
    current_dialog: Option<Box<dyn Component>>,
    signature_help: signature_help::SignatureHelpState,
    keyboard_shortcuts: Option<crate::ui::KeyboardShortcuts>,
    shortcut_help_regions: Vec<crate::ui::ShortcutHelpRegion>,

    /// Number prefix for repeating commands
    repeater: Option<u16>,

    /// Starting point of current selection
    selection_start: Option<Point>,

    /// Current selection rectangle
    selection: Option<Rect>,

    /// Named registers for storing text (like vim registers)
    registers: HashMap<char, Content>,

    /// System clipboard bridge for the default register.
    clipboard: Box<dyn ClipboardProvider>,

    /// Map of diagnostics per file uri
    diagnostics: HashMap<String, Vec<Diagnostic>>,
    diagnostic_reports: diagnostics::DiagnosticReports,
    diagnostic_cache: Option<diagnostic_cache::DiagnosticCache>,

    /// Indentation rules per file type
    indentation: HashMap<String, Indentation>,

    /// Pending render commands from plugins
    render_commands: VecDeque<RenderCommand>,

    /// Plugin overlay manager
    overlay_manager: plugin::OverlayManager,

    /// Persistent virtual text decorations owned by plugins.
    decoration_manager: plugin::DecorationManager,

    gutter_sign_manager: plugin::GutterSignManager,

    panel_manager: plugin::PanelManager,

    /// Mouse-captured pane or split divider; passive mouse motion never starts a drag.
    divider_drag: Option<DividerDrag>,

    workspace_manager: plugin::WorkspaceManager,

    window_bar_manager: plugin::WindowBarManager,

    directory_watchers: HashMap<i32, DirectoryWatcher>,

    pending_plugin_document_symbols: HashMap<i64, PendingDocumentSymbols>,
    pending_plugin_workspace_symbols: HashMap<i64, RequestId>,
    pending_plugin_references: HashMap<i64, RequestId>,
    pending_plugin_inlay_hints: HashMap<i64, RequestId>,
    pending_lsp_edit_requests: HashMap<i64, PendingLspEdit>,
    /// LSP request currently owning the visible, cancellable code-action picker.
    pending_code_action_request: Option<i64>,
    pending_lsp_format_saves: HashMap<i64, PendingLspFormatSave>,
    pending_lsp_revision_snapshots: HashMap<i64, Vec<(String, u64)>>,
    pending_completions: HashMap<i64, PendingCompletion>,
    /// Definition requests whose eventual destination must precede queued CTRL-O/CTRL-I actions.
    pending_definition_requests: HashSet<i64>,
    /// Jumplist traversal typed while a definition request is still in flight.
    deferred_jump_navigation: VecDeque<Action>,
    pending_completion_resolutions: HashMap<i64, completion_resolve::PendingCompletionResolution>,
    scheduled_completion: Option<ScheduledCompletion>,
    // Keep optional AI state out of Editor values and the startup futures that own them.
    inline_completion: Box<inline_completion::InlineCompletionState>,
    completion_snapshot: Option<CompletionSnapshot>,
    /// Insert-mode placeholder anchors belonging to the most recently expanded snippet.
    snippet_session: Option<snippet::SnippetSession>,
}

/// Terminal-independent owner used by the local detach protocol. It keeps the real
/// editor, Husk runtime, LSP client, Codex task, buffers, and render state in the server
/// process while replaceable clients only send normalized input and paint rows.
pub struct DetachedEditorCore {
    editor: Editor,
    runtime: Runtime,
    render_buffer: RenderBuffer,
    revision: u64,
    rows: Vec<String>,
    row_spans: Vec<Vec<crate::headless::StyledSpan>>,
    serialized_render_generation: u64,
    serialized_width: usize,
    cursor: (usize, usize),
    cursor_state: crate::terminal_output::CursorState,
    stopped: bool,
    pending_paste: String,
}

impl DetachedEditorCore {
    /// Moves an editor into terminal-independent detached ownership.
    ///
    /// The constructor initializes a fresh plugin runtime and render model
    /// while retaining all editor, LSP, recovery, and Codex state.
    pub async fn new(mut editor: Editor) -> anyhow::Result<Self> {
        editor.terminal_output_enabled = false;
        editor.notification_exposure = None;
        let mut runtime =
            Runtime::try_new_with_permissions(editor.config.plugin_permissions.clone())?;
        runtime.set_typecheck_enabled(!editor.config.disable_plugin_typecheck);
        editor.refresh_plugin_snapshots(&mut runtime, true, true, true)?;
        for (name, path) in &editor.config.plugins {
            let path = Config::resolve_plugin_path(path);
            editor.plugin_registry.add(name, path.as_str());
        }
        editor.plugin_registry.initialize(&mut runtime).await?;
        editor
            .plugin_registry
            .notify(&mut runtime, "editor:ready", json!({}))
            .await?;
        editor.restore_agent_plugin_state(&mut runtime).await?;
        editor.notify_pane_restore_intents(&mut runtime).await?;
        editor.ensure_current_buffer_lsp_opened().await?;
        let mut render_buffer = RenderBuffer::new(
            editor.size.0 as usize,
            editor.size.1 as usize,
            &Style::default(),
        );
        editor.render(&mut render_buffer)?;
        let rows = render_text_rows(&render_buffer);
        let row_spans = render_styled_rows(&render_buffer, &editor.theme.style);
        let cursor = editor
            .render_cursor_position()
            .unwrap_or((editor.cx, editor.cy));
        let cursor_state = editor.terminal_cursor_state();
        let serialized_render_generation = editor.render_generation;
        let serialized_width = render_buffer.width;
        Ok(Self {
            editor,
            runtime,
            render_buffer,
            revision: 0,
            rows,
            row_spans,
            serialized_render_generation,
            serialized_width,
            cursor,
            cursor_state,
            stopped: false,
            pending_paste: String::new(),
        })
    }

    #[must_use]
    pub fn snapshot(&self, last_revision: Option<u64>) -> crate::headless::RenderDelta {
        crate::headless::RenderDelta {
            revision: self.revision,
            lines: if last_revision == Some(self.revision) {
                Vec::new()
            } else {
                self.rows
                    .iter()
                    .enumerate()
                    .map(|(row, text)| crate::headless::LinePatch {
                        row,
                        text: text.clone(),
                        spans: self.row_spans.get(row).cloned().unwrap_or_default(),
                    })
                    .collect()
            },
            cursor: self.cursor,
            cursor_state: Some(self.cursor_state),
        }
    }

    pub async fn input(
        &mut self,
        event: crate::headless::InputEvent,
    ) -> anyhow::Result<crate::headless::RenderDelta> {
        let event = match event {
            crate::headless::InputEvent::PasteChunk { text, final_chunk } => {
                let next_size = self.pending_paste.len().saturating_add(text.len());
                if next_size > crate::headless::MAX_PENDING_PASTE_BYTES {
                    self.pending_paste.clear();
                    anyhow::bail!(
                        "detach paste exceeds {} bytes before completion",
                        crate::headless::MAX_PENDING_PASTE_BYTES
                    );
                }
                self.pending_paste.push_str(&text);
                if !final_chunk {
                    return Ok(self.snapshot(Some(self.revision)));
                }
                Event::Paste(std::mem::take(&mut self.pending_paste))
            }
            event => {
                self.pending_paste.clear();
                detached_input_to_crossterm(event)
            }
        };
        let processed = self
            .editor
            .process_editor_event(
                event,
                &mut self.render_buffer,
                &mut self.runtime,
                EventRenderMode::CoalescedNavigation,
            )
            .await?;
        self.stopped = processed.quit;
        if processed.navigation_deferred {
            self.editor
                .finish_navigation_batch(&mut self.render_buffer, &mut self.runtime)
                .await?;
        } else {
            self.editor
                .service_background(&mut self.render_buffer, &mut self.runtime)
                .await?;
        }
        if self.editor.persist_session_snapshot(/*force*/ false) {
            self.editor.render(&mut self.render_buffer)?;
        }
        self.finish_render()
    }

    pub async fn resize(
        &mut self,
        columns: u16,
        rows: u16,
    ) -> anyhow::Result<crate::headless::RenderDelta> {
        self.editor
            .process_editor_event(
                Event::Resize(columns, rows),
                &mut self.render_buffer,
                &mut self.runtime,
                EventRenderMode::Immediate,
            )
            .await?;
        self.editor
            .service_background(&mut self.render_buffer, &mut self.runtime)
            .await?;
        self.finish_render()
    }

    pub async fn focus(&mut self, focused: bool) -> anyhow::Result<crate::headless::RenderDelta> {
        let event = if focused {
            Event::FocusGained
        } else {
            Event::FocusLost
        };
        self.editor
            .process_editor_event(
                event,
                &mut self.render_buffer,
                &mut self.runtime,
                EventRenderMode::Immediate,
            )
            .await?;
        self.editor
            .service_background(&mut self.render_buffer, &mut self.runtime)
            .await?;
        self.finish_render()
    }

    /// Advance terminal-independent background work while no client is attached.
    ///
    /// This is the ownership guarantee behind detach: plugin processes, LSP messages,
    /// timers, directory watches, and agent events keep flowing in the core process.
    pub async fn tick(&mut self) -> anyhow::Result<Option<crate::headless::RenderDelta>> {
        let render_generation = self.editor.render_generation;
        self.editor
            .service_background(&mut self.render_buffer, &mut self.runtime)
            .await?;
        if self.editor.persist_session_snapshot(/*force*/ false) {
            self.editor.render(&mut self.render_buffer)?;
        }
        if self.editor.render_generation == render_generation {
            perf::increment("detach:idle_tick", 1);
            return Ok(None);
        }
        perf::increment("detach:rendered_tick", 1);
        self.finish_render().map(Some)
    }

    #[must_use]
    pub fn stopped(&self) -> bool {
        self.stopped
    }

    pub fn persist(&mut self) {
        self.editor.persist_session_snapshot(/*force*/ true);
    }

    pub fn clear_pending_paste(&mut self) {
        self.pending_paste.clear();
    }

    #[doc(hidden)]
    pub fn benchmark_incremental_frame(
        &mut self,
        iteration: usize,
    ) -> anyhow::Result<crate::headless::RenderDelta> {
        let row = self.render_buffer.height / 2;
        let text = if iteration.is_multiple_of(2) {
            "a"
        } else {
            "b"
        };
        self.render_buffer.set_text(0, row, text, &Style::default());
        let previous = self
            .editor
            .previous_render_buffer
            .as_mut()
            .expect("detached initialization commits an initial frame");
        let changes = self.render_buffer.diff(previous);
        previous.apply_changes(&changes);
        self.editor.last_detached_changed_rows.clear();
        for change in &changes {
            if self.editor.last_detached_changed_rows.last() != Some(&change.y) {
                self.editor.last_detached_changed_rows.push(change.y);
            }
        }
        self.editor.render_generation = self.editor.render_generation.wrapping_add(1);
        self.finish_render()
    }

    /// Prepares a pending release modal only after a client authenticates.
    pub fn prepare_startup_whats_new(&mut self) -> anyhow::Result<bool> {
        if !self.editor.prepare_startup_whats_new() {
            return Ok(false);
        }
        self.editor.render(&mut self.render_buffer)?;
        self.finish_render()?;
        Ok(true)
    }

    /// Opens fresh-install onboarding only after a detached client authenticates.
    pub fn prepare_startup_welcome(&mut self) -> anyhow::Result<bool> {
        if !self.editor.prepare_startup_welcome() {
            return Ok(false);
        }
        self.editor.render(&mut self.render_buffer)?;
        self.finish_render()?;
        Ok(true)
    }

    /// Claims the version only after its first frame reaches an attached client.
    pub fn mark_whats_new_presented(&mut self) {
        self.editor.mark_whats_new_presented();
    }

    /// Starts exposure only for the exact frame successfully sent to a client.
    pub fn mark_frame_presented(&mut self, revision: u64) {
        self.editor.notification_client_attached = true;
        if self.revision == revision {
            self.editor.notification_frame_presented(Instant::now());
        } else {
            self.editor.notification_exposure = None;
        }
    }

    pub fn client_disconnected(&mut self) {
        self.editor.notification_client_attached = false;
        self.editor.notification_exposure = None;
    }

    pub async fn shutdown(&mut self) {
        self.editor.shutdown_services(&mut self.runtime).await;
    }

    fn finish_render(&mut self) -> anyhow::Result<crate::headless::RenderDelta> {
        let _span = perf::PerfSpan::start("detach:serialize_frame");
        let next_cursor = self
            .editor
            .render_cursor_position()
            .unwrap_or((self.editor.cx, self.editor.cy));
        let next_cursor_state = self.editor.terminal_cursor_state();
        let generation_delta = self
            .editor
            .render_generation
            .wrapping_sub(self.serialized_render_generation);
        let dimensions_unchanged = self.render_buffer.width == self.serialized_width
            && self.render_buffer.height == self.rows.len()
            && self.row_spans.len() == self.rows.len();
        let lines = if dimensions_unchanged && generation_delta <= 1 {
            if generation_delta == 0 {
                Vec::new()
            } else {
                self.serialize_changed_rows()
            }
        } else {
            self.serialize_full_frame()
        };
        if !lines.is_empty() || next_cursor != self.cursor || next_cursor_state != self.cursor_state
        {
            self.revision = self.revision.saturating_add(1);
        }
        perf::gauge_max("detach:changed_rows", lines.len() as u64);
        self.serialized_render_generation = self.editor.render_generation;
        self.serialized_width = self.render_buffer.width;
        self.cursor = next_cursor;
        self.cursor_state = next_cursor_state;
        Ok(crate::headless::RenderDelta {
            revision: self.revision,
            lines,
            cursor: self.cursor,
            cursor_state: Some(self.cursor_state),
        })
    }

    fn serialize_changed_rows(&mut self) -> Vec<crate::headless::LinePatch> {
        let mut lines = Vec::with_capacity(self.editor.last_detached_changed_rows.len());
        for &row in &self.editor.last_detached_changed_rows {
            let start = row.saturating_mul(self.render_buffer.width);
            let end = start.saturating_add(self.render_buffer.width);
            let Some(cells) = self.render_buffer.cells.get(start..end) else {
                continue;
            };
            let text = render_text_row(cells);
            let spans = render_styled_row(cells, &self.editor.theme.style);
            if self.rows.get(row) == Some(&text) && self.row_spans.get(row) == Some(&spans) {
                continue;
            }
            self.rows[row].clone_from(&text);
            self.row_spans[row].clone_from(&spans);
            lines.push(crate::headless::LinePatch { row, text, spans });
        }
        lines
    }

    fn serialize_full_frame(&mut self) -> Vec<crate::headless::LinePatch> {
        let next_rows = render_text_rows(&self.render_buffer);
        let next_row_spans = render_styled_rows(&self.render_buffer, &self.editor.theme.style);
        let lines = next_rows
            .iter()
            .enumerate()
            .filter(|(row, text)| {
                self.rows.get(*row) != Some(*text)
                    || self.row_spans.get(*row) != next_row_spans.get(*row)
            })
            .map(|(row, text)| crate::headless::LinePatch {
                row,
                text: text.clone(),
                spans: next_row_spans.get(row).cloned().unwrap_or_default(),
            })
            .collect();
        self.rows = next_rows;
        self.row_spans = next_row_spans;
        lines
    }
}

fn render_text_rows(buffer: &RenderBuffer) -> Vec<String> {
    buffer
        .cells
        .chunks(buffer.width.max(1))
        .map(render_text_row)
        .collect()
}

fn render_text_row(row: &[render_buffer::Cell]) -> String {
    let mut text = String::new();
    let mut column = 0;
    while let Some(cell) = row.get(column) {
        text.push_str(&cell.text);
        column += display_width(&cell.text).max(1);
    }
    text
}

fn render_styled_rows(
    buffer: &RenderBuffer,
    theme_style: &Style,
) -> Vec<Vec<crate::headless::StyledSpan>> {
    buffer
        .cells
        .chunks(buffer.width.max(1))
        .map(|row| render_styled_row(row, theme_style))
        .collect()
}

fn render_styled_row(
    row: &[render_buffer::Cell],
    theme_style: &Style,
) -> Vec<crate::headless::StyledSpan> {
    let mut spans: Vec<crate::headless::StyledSpan> = Vec::new();
    let mut column = 0;
    while let Some(cell) = row.get(column) {
        let (fg, bg) = rendering::resolve_cell_colors(&cell.style, theme_style);
        let style = Style {
            fg: Some(fg),
            bg: Some(bg),
            bold: cell.style.bold,
            italic: cell.style.italic,
            underline: cell.style.underline,
        };
        if let Some(span) = spans.last_mut().filter(|span| span.style == style) {
            span.text.push_str(&cell.text);
        } else {
            spans.push(crate::headless::StyledSpan {
                text: cell.text.clone(),
                style,
            });
        }
        column += display_width(&cell.text).max(1);
    }
    spans
}

fn detached_input_to_crossterm(event: crate::headless::InputEvent) -> Event {
    match event {
        crate::headless::InputEvent::Paste { text }
        | crate::headless::InputEvent::PasteChunk { text, .. } => Event::Paste(text),
        crate::headless::InputEvent::Mouse { event } => Event::Mouse(event),
        crate::headless::InputEvent::Key {
            code,
            modifiers,
            key_kind,
        } => {
            let code = match code {
                crate::headless::KeyCode::Character(character) => KeyCode::Char(character),
                crate::headless::KeyCode::Enter => KeyCode::Enter,
                crate::headless::KeyCode::Backspace => KeyCode::Backspace,
                crate::headless::KeyCode::Escape => KeyCode::Esc,
                crate::headless::KeyCode::Tab => KeyCode::Tab,
                crate::headless::KeyCode::BackTab => KeyCode::BackTab,
                crate::headless::KeyCode::Function(number) => KeyCode::F(number),
                crate::headless::KeyCode::Delete => KeyCode::Delete,
                crate::headless::KeyCode::Left => KeyCode::Left,
                crate::headless::KeyCode::Right => KeyCode::Right,
                crate::headless::KeyCode::Up => KeyCode::Up,
                crate::headless::KeyCode::Down => KeyCode::Down,
                crate::headless::KeyCode::Home => KeyCode::Home,
                crate::headless::KeyCode::End => KeyCode::End,
                crate::headless::KeyCode::PageUp => KeyCode::PageUp,
                crate::headless::KeyCode::PageDown => KeyCode::PageDown,
            };
            let mut key_modifiers = KeyModifiers::NONE;
            for modifier in modifiers {
                key_modifiers |= match modifier {
                    crate::headless::KeyModifier::Control => KeyModifiers::CONTROL,
                    crate::headless::KeyModifier::Alt => KeyModifiers::ALT,
                    crate::headless::KeyModifier::Shift => KeyModifiers::SHIFT,
                };
            }
            let kind = match key_kind {
                crate::headless::KeyKind::Press => KeyEventKind::Press,
                crate::headless::KeyKind::Repeat => KeyEventKind::Repeat,
            };
            Event::Key(KeyEvent::new_with_kind(code, key_modifiers, kind))
        }
    }
}

