    /// Creates a new Editor instance with the given configuration
    ///
    /// # Arguments
    /// * `lsp` - LSP client for code intelligence features
    /// * `config` - Editor configuration settings
    /// * `theme` - Visual theme settings
    /// * `buffers` - Initial set of buffers to edit
    ///
    /// # Returns
    /// A Result containing either the new Editor or an error if initialization fails
    pub fn new(
        lsp: Box<dyn LspClient>,
        config: Config,
        theme: Theme,
        buffers: Vec<Buffer>,
    ) -> anyhow::Result<Self> {
        Self::new_with_preferences(lsp, config, theme, buffers, PreferencesStore::in_memory())
    }

    pub fn new_with_preferences(
        lsp: Box<dyn LspClient>,
        config: Config,
        theme: Theme,
        buffers: Vec<Buffer>,
        preferences: PreferencesStore,
    ) -> anyhow::Result<Self> {
        let size = terminal::size()?;
        Self::with_size_and_preferences(
            lsp,
            size.0 as usize,
            size.1 as usize,
            config,
            theme,
            buffers,
            preferences,
        )
    }

    /// Defers release announcements while crash recovery owns the first frame.
    pub fn suppress_startup_whats_new(&mut self) {
        self.whats_new_startup_pending = false;
    }

    fn open_whats_new_panel(&mut self) -> bool {
        if !WhatsNewPanel::fits(self.vwidth(), self.vheight()) {
            return false;
        }

        let version = env!("CARGO_PKG_VERSION");
        let notes = ReleaseNotes::bundled(version, self.preferences.last_seen_version());
        let refresh = if self.config.fetch_release_notes.unwrap_or(true) {
            let (sender, receiver) = tokio::sync::oneshot::channel();
            let fallback = notes.clone();
            tokio::spawn(async move {
                let result = ReleaseNotes::fetch(version, &fallback)
                    .await
                    .map_err(|error| format!("{error:#}"));
                let _ = sender.send(result);
            });
            Some(receiver)
        } else {
            None
        };

        self.current_dialog = Some(Box::new(WhatsNewPanel::new(self, notes, refresh)));
        self.whats_new_startup_pending = false;
        self.whats_new_needs_persistence = true;
        true
    }

    fn prepare_startup_whats_new(&mut self) -> bool {
        self.whats_new_auto_presentation_enabled = true;
        self.whats_new_startup_pending
            && self.current_dialog.is_none()
            && self.open_whats_new_panel()
    }

    fn mark_whats_new_presented(&mut self) {
        if !std::mem::take(&mut self.whats_new_needs_persistence) {
            return;
        }
        if let Err(error) = self
            .preferences
            .set_last_seen_version(env!("CARGO_PKG_VERSION"))
        {
            log!("could not persist the displayed release version: {error}");
        }
    }

    /// Requests the editor-native welcome for a genuinely fresh installation.
    ///
    /// Detached owners retain the request until an authenticated client attaches.
    pub fn enable_first_launch_welcome(&mut self, first_launch: bool) {
        self.welcome_startup_pending = first_launch && !self.preferences.welcome_completed();
        if self.welcome_startup_pending {
            self.whats_new_startup_pending = false;
        }
    }

    fn open_welcome_panel(&mut self) -> bool {
        if !WelcomePanel::fits(self.vwidth(), self.vheight()) {
            return false;
        }
        let can_resume = self
            .preferences
            .tutorial_progress()
            .is_some_and(|progress| !progress.completed);
        self.current_dialog = Some(Box::new(WelcomePanel::new(self, can_resume)));
        self.welcome_startup_pending = false;
        true
    }

    fn prepare_startup_welcome(&mut self) -> bool {
        self.welcome_startup_pending && self.current_dialog.is_none() && self.open_welcome_panel()
    }

    fn finish_welcome(&mut self) {
        self.welcome_startup_pending = false;
        if let Err(error) = self.preferences.complete_welcome() {
            log!("could not persist first-run welcome decision: {error}");
        }
    }

    async fn start_tutorial(
        &mut self,
        progress: TutorialProgress,
        buffer: &mut RenderBuffer,
        runtime: &mut Runtime,
    ) -> anyhow::Result<()> {
        if self.tutorial_controller.is_some() {
            self.finish_tutorial(/*completed*/ false, buffer, runtime)
                .await?;
        }

        self.finish_welcome();
        self.release_current_dialog_callbacks(runtime);
        self.current_dialog = None;
        self.sync_to_window();
        let original_window_layout = self.window_manager.snapshot();
        let original_buffer_index = self.buffer_manager.active_index();
        let practice = Buffer::new(/*file*/ None, PRACTICE_CONTENTS.to_string());
        let practice_buffer_id = practice.id();
        self.buffer_manager.push_buffer(practice);
        let practice_index = self.buffer_manager.len() - 1;
        self.tutorial_controller = Some(TutorialController::new(
            progress,
            practice_buffer_id,
            original_buffer_index,
            original_window_layout,
        ));
        self.mode = Mode::Normal;
        self.splash_dismissed = true;
        if let Some(window) = self.window_manager.active_window_mut() {
            window.buffer_index = practice_index;
        }
        self.set_current_buffer(buffer, practice_index).await?;
        self.persist_tutorial_progress();
        self.render(buffer)
    }

    async fn finish_tutorial(
        &mut self,
        completed: bool,
        buffer: &mut RenderBuffer,
        runtime: &mut Runtime,
    ) -> anyhow::Result<()> {
        let Some(mut tutorial) = self.tutorial_controller.take() else {
            return Ok(());
        };
        if completed {
            while !tutorial.progress().completed {
                tutorial.advance();
            }
        }
        if let Err(error) = self
            .preferences
            .set_tutorial_progress(tutorial.progress().clone())
        {
            log!("could not persist guided-tour progress: {error}");
        }

        self.release_current_dialog_callbacks(runtime);
        self.current_dialog = None;
        if let Some(index) = self
            .buffer_manager
            .iter()
            .position(|candidate| candidate.id() == tutorial.practice_buffer_id)
        {
            self.buffer_manager.remove_buffer(index);
        }

        let buffer_map = (0..self.buffer_manager.len())
            .map(|index| (index, index))
            .collect::<HashMap<_, _>>();
        if let Some(restored) = WindowManager::from_snapshot(
            &tutorial.original_window_layout,
            (self.size.0 as usize, self.size.1 as usize),
            &buffer_map,
        ) {
            self.window_manager = restored;
        }
        self.buffer_manager
            .set_active_index(tutorial.original_buffer_index);
        self.sync_with_window();
        self.mode = Mode::Normal;
        self.highlight_cache.clear();
        self.layout_cache.borrow_mut().clear();
        self.force_full_redraw = true;
        if completed {
            self.last_error = Some("Red tour complete — your project was never modified".into());
        }
        self.render(buffer)
    }

    fn persist_tutorial_progress(&mut self) {
        let Some(progress) = self
            .tutorial_controller
            .as_ref()
            .map(|tutorial| tutorial.progress().clone())
        else {
            return;
        };
        if let Err(error) = self.preferences.set_tutorial_progress(progress) {
            log!("could not persist guided-tour progress: {error}");
        }
    }

    fn tutorial_shortcut(&self) -> Option<String> {
        let tutorial = self.tutorial_controller.as_ref()?;
        let action = tutorial
            .lesson()?
            .suggested_action(tutorial.progress().phase)?;
        command_palette::shortcuts_for_action(&self.config.keys, &action)
            .into_iter()
            .next()
    }

    async fn observe_tutorial_action(
        &mut self,
        action: &Action,
        buffer: &mut RenderBuffer,
        runtime: &mut Runtime,
    ) -> anyhow::Result<()> {
        if matches!(
            action,
            Action::StartTutorial(_)
                | Action::ResumeTutorial
                | Action::AdvanceTutorial
                | Action::ExitTutorial
        ) {
            return Ok(());
        }
        let Some(tutorial) = &mut self.tutorial_controller else {
            return Ok(());
        };
        let observation = tutorial.observe(action);
        if observation == TutorialObservation::Unchanged {
            return Ok(());
        }
        self.persist_tutorial_progress();
        if observation == TutorialObservation::Completed {
            self.finish_tutorial(/*completed*/ true, buffer, runtime)
                .await?;
        } else {
            self.render(buffer)?;
        }
        Ok(())
    }

    async fn accept_tutorial_proposal(
        &mut self,
        buffer: &mut RenderBuffer,
        runtime: &mut Runtime,
    ) -> anyhow::Result<()> {
        let Some(practice_id) = self
            .tutorial_controller
            .as_ref()
            .map(|tutorial| tutorial.practice_buffer_id)
        else {
            return Ok(());
        };
        let Some(index) = self
            .buffer_manager
            .iter()
            .position(|candidate| candidate.id() == practice_id)
        else {
            return Ok(());
        };
        if index != self.buffer_manager.active_index() {
            if let Some(window) = self.window_manager.active_window_mut() {
                window.buffer_index = index;
            }
            self.set_current_buffer(buffer, index).await?;
        }
        let contents = self.current_buffer().contents();
        let old = "prices.iter().sum()";
        if let Some((line, text)) = contents
            .lines()
            .enumerate()
            .find(|(_, line)| line.contains(old))
        {
            let character = text
                .find(old)
                .map(|byte| text[..byte].chars().count())
                .unwrap_or_default();
            let start = TextPosition::new(line, character);
            let end = TextPosition::new(line, character + old.chars().count());
            self.begin_transaction("accept tutorial practice proposal");
            self.replace_range(TextRange::new(start, end), "prices.iter().copied().sum()");
            self.commit_transaction(self.cursor_snapshot());
            self.notify_change(runtime).await?;
        }
        Ok(())
    }

    /// Synchronizes the editor's state with the active window
    fn sync_with_window(&mut self) {
        if let Some(window) = self.window_manager.active_window() {
            self.buffer_manager.set_active_index(window.buffer_index);
            self.vtop = window.vtop;
            self.vleft = window.vleft;
            self.skipcol = window.skipcol;
            self.wrap = window.wrap;
            self.cx = window.cx;
            self.cy = window.cy;
            self.cursor_goal = window.cursor_goal;
            self.vx = window.vx;
        }
    }

    /// Synchronizes the active window with the editor's state
    fn sync_to_window(&mut self) {
        if let Some(window) = self.window_manager.active_window_mut() {
            window.buffer_index = self.buffer_manager.active_index();
            window.vtop = self.vtop;
            window.vleft = self.vleft;
            window.skipcol = self.skipcol;
            window.wrap = self.wrap;
            window.cx = self.cx;
            window.cy = self.cy;
            window.cursor_goal = self.cursor_goal;
            window.vx = self.vx;
        }
    }

    #[cfg(test)]
    fn editor_view_state(&self) -> EditorViewState {
        EditorViewState {
            vtop: self.vtop,
            vleft: self.vleft,
            skipcol: self.skipcol,
            cy: self.cy,
            wrap: self.wrap,
        }
    }

    fn rendered_viewport(&self) -> Option<RenderedViewport> {
        let window = self.window_manager.active_window()?;
        Some(RenderedViewport {
            buffer_id: self.current_buffer().id(),
            revision: self.current_buffer().revision(),
            vtop: self.vtop,
            vleft: self.vleft,
            skipcol: self.skipcol,
            wrap: self.wrap,
            terminal_size: self.size,
            bounds: (
                window.position.x,
                window.position.y,
                window.inner_width(),
                window.inner_height(),
            ),
            content_top: self.window_content_top(window),
            gutter_width: self.gutter_width_for_window(window),
        })
    }

    fn active_window_with_editor_view(&self) -> Option<crate::window::Window> {
        let mut window = self.window_manager.active_window()?.clone();
        window.buffer_index = self.buffer_manager.active_index();
        window.vtop = self.vtop;
        window.vleft = self.vleft;
        window.skipcol = self.skipcol;
        window.wrap = self.wrap;
        window.cx = self.cx;
        window.cy = self.cy;
        window.cursor_goal = self.cursor_goal;
        window.vx = self.vx;
        Some(window)
    }

    fn finish_cursor_motion(
        &mut self,
        buffer: &mut RenderBuffer,
        preserve_cursor_goal: bool,
    ) -> anyhow::Result<()> {
        if !preserve_cursor_goal {
            self.refresh_cursor_goal();
        }
        self.fix_cursor_pos();
        // Apply scrolloff now so a motion that scrolls renders exactly once
        // instead of drawing a pre-scroll frame that check_bounds immediately
        // invalidates.
        self.check_bounds();
        self.sync_to_window();
        let viewport_changed = self.last_rendered_viewport != self.rendered_viewport();

        if self.render_is_deferred() {
            self.request_motion_render(if viewport_changed {
                MotionRender::Window
            } else {
                MotionRender::Cursor
            });
            return Ok(());
        }

        if viewport_changed {
            self.render_motion_frame(buffer)
        } else if self.can_render_cursor_motion_delta() {
            self.render_cursor_motion_delta(buffer)
        } else if self.relative_line_numbers_enabled()
            || self.uses_synthetic_block_cursor()
            || !self.last_rendered_bracket_rows.is_empty()
            || self.matching_bracket_positions().is_some()
        {
            self.render_motion_frame(buffer)
        } else {
            self.draw_cursor_preserving_cursor_goal()?;
            if self.terminal_output_enabled {
                self.flush_terminal_output()?;
            }
            Ok(())
        }
    }

    fn flush_terminal_output(&mut self) -> std::io::Result<()> {
        self.stdout.flush()?;
        #[cfg(test)]
        {
            self.flushed_terminal_cursor = self.pending_terminal_cursor;
            self.terminal_flush_generation = self.terminal_flush_generation.wrapping_add(1);
        }
        Ok(())
    }

    fn set_active_window(&mut self, window_id: usize) -> bool {
        if window_id == self.window_manager.active_window_id() {
            return false;
        }

        self.clear_pane_zoom();
        self.sync_to_window();
        self.window_manager.set_active(window_id);
        self.sync_with_window();
        true
    }

    fn focus_ring(&self) -> Vec<FocusTarget> {
        let mut targets = self
            .panel_manager
            .focusable_ids_for_side(plugin::PanelSide::Top)
            .into_iter()
            .map(FocusTarget::Panel)
            .collect::<Vec<_>>();
        targets.extend(
            self.panel_manager
                .focusable_ids_for_side(plugin::PanelSide::Left)
                .into_iter()
                .map(FocusTarget::Panel),
        );
        targets.extend(
            self.window_manager
                .windows()
                .into_iter()
                .map(|window| FocusTarget::Window(window.id)),
        );
        targets.extend(
            self.panel_manager
                .focusable_ids_for_side(plugin::PanelSide::Right)
                .into_iter()
                .map(FocusTarget::Panel),
        );
        targets.extend(
            self.panel_manager
                .focusable_ids_for_side(plugin::PanelSide::Bottom)
                .into_iter()
                .map(FocusTarget::Panel),
        );
        targets
    }

    fn current_focus_target(&self) -> Option<FocusTarget> {
        self.panel_manager
            .focused_panel_id()
            .map(|id| FocusTarget::Panel(id.to_string()))
            .or_else(|| {
                self.window_manager
                    .active_stable_window_id()
                    .map(FocusTarget::Window)
            })
    }

    fn next_focus_target(&self, forward: bool) -> Option<FocusTarget> {
        let targets = self.focus_ring();
        if targets.len() <= 1 {
            return None;
        }
        let current = self.current_focus_target()?;
        let index = targets.iter().position(|target| target == &current)?;
        let next = if forward {
            (index + 1) % targets.len()
        } else if index == 0 {
            targets.len() - 1
        } else {
            index - 1
        };
        targets.get(next).cloned()
    }

    fn focus_target(&mut self, target: &FocusTarget) -> bool {
        if self
            .zoomed_pane
            .as_ref()
            .is_some_and(|zoomed| zoomed != target)
        {
            self.clear_pane_zoom();
        }
        match target {
            FocusTarget::Panel(id) => {
                if self.panel_manager.focused_panel_id() == Some(id.as_str()) {
                    return false;
                }
                self.panel_manager.focus_text_panel_composer(id)
                    || self.panel_manager.focus_panel(id)
            }
            FocusTarget::Window(id) => {
                let had_focused_panel = self.panel_manager.has_focused_panel();
                self.panel_manager.focus_editor();
                let switched_window = self
                    .window_manager
                    .window_index(*id)
                    .is_some_and(|index| self.set_active_window(index));
                had_focused_panel || switched_window
            }
        }
    }

    async fn cycle_focus(
        &mut self,
        forward: bool,
        buffer: &mut RenderBuffer,
    ) -> anyhow::Result<()> {
        let Some(target) = self.next_focus_target(forward) else {
            return Ok(());
        };
        let previous_window = self.window_manager.active_stable_window_id();
        if !self.focus_target(&target) {
            return Ok(());
        }
        if previous_window != self.window_manager.active_stable_window_id() {
            self.request_diagnostics().await?;
        }
        self.render(buffer)
    }

    async fn move_window_in_direction(
        &mut self,
        direction: crate::window::Direction,
        buffer: &mut RenderBuffer,
    ) -> anyhow::Result<()> {
        if let Some(panel_id) = self.panel_manager.focused_panel_id() {
            if let Some((side, _)) = self.panel_manager.panel_layout(panel_id) {
                let points_into_editor = matches!(
                    (side, direction),
                    (plugin::PanelSide::Left, crate::window::Direction::Right)
                        | (plugin::PanelSide::Right, crate::window::Direction::Left)
                        | (plugin::PanelSide::Top, crate::window::Direction::Down)
                        | (plugin::PanelSide::Bottom, crate::window::Direction::Up)
                );
                if points_into_editor {
                    if let Some(window_id) = self.window_manager.active_stable_window_id() {
                        if self.focus_target(&FocusTarget::Window(window_id)) {
                            self.render(buffer)?;
                        }
                    }
                    return Ok(());
                }
            }
        }

        if let Some(target_id) = self.window_manager.find_window_in_direction(direction) {
            if self.set_active_window(target_id) {
                self.panel_manager.focus_editor();
                self.request_diagnostics().await?;
                self.render(buffer)?;
                return Ok(());
            }
        }

        let side = Self::panel_side_for_direction(direction);
        if let Some(panel_id) = self
            .panel_manager
            .focusable_ids_for_side(side)
            .into_iter()
            .next()
        {
            if self.focus_target(&FocusTarget::Panel(panel_id)) {
                self.render(buffer)?;
                return Ok(());
            }
        }

        if self.config.wrap_window_navigation.unwrap_or(true) {
            if let Some(target_id) = self.window_manager.find_window_across_edge(direction) {
                if self.set_active_window(target_id) {
                    self.panel_manager.focus_editor();
                    self.request_diagnostics().await?;
                    self.render(buffer)?;
                    return Ok(());
                }
            }
        }

        let message = match direction {
            crate::window::Direction::Up => "no window above",
            crate::window::Direction::Down => "no window below",
            crate::window::Direction::Left => "no window to the left",
            crate::window::Direction::Right => "no window to the right",
        };
        self.set_routine_warning(Some(message.to_string()));
        self.draw_commandline(buffer);
        Ok(())
    }

    fn panel_side_for_direction(direction: crate::window::Direction) -> plugin::PanelSide {
        match direction {
            crate::window::Direction::Up => plugin::PanelSide::Top,
            crate::window::Direction::Down => plugin::PanelSide::Bottom,
            crate::window::Direction::Left => plugin::PanelSide::Left,
            crate::window::Direction::Right => plugin::PanelSide::Right,
        }
    }

    fn move_focused_window_to_edge(
        &mut self,
        direction: crate::window::Direction,
        buffer: &mut RenderBuffer,
    ) -> anyhow::Result<()> {
        if let Some(panel_id) = self.panel_manager.focused_panel_id().map(str::to_string) {
            if let Some((current_side, current_size)) = self.panel_manager.panel_layout(&panel_id) {
                let side = Self::panel_side_for_direction(direction);
                let current_is_vertical = matches!(
                    current_side,
                    plugin::PanelSide::Left | plugin::PanelSide::Right
                );
                let target_is_vertical =
                    matches!(side, plugin::PanelSide::Left | plugin::PanelSide::Right);
                let default_size = if target_is_vertical {
                    usize::from(self.size.0)
                        .saturating_mul(2)
                        .saturating_div(5)
                        .max(MIN_DOCKED_PANEL_WIDTH)
                } else {
                    usize::from(self.size.1)
                        .saturating_sub(2)
                        .saturating_div(3)
                        .max(MIN_DOCKED_PANEL_HEIGHT)
                };
                let size = if current_is_vertical == target_is_vertical {
                    current_size
                } else {
                    self.panel_manager
                        .panel_preferred_size(&panel_id, side)
                        .unwrap_or(default_size)
                };

                if self.set_panel_size(&panel_id, side, size) {
                    self.render(buffer)?;
                }
                return Ok(());
            }
        }

        if self.update_window_layout(|windows| windows.move_window_to_edge(direction)) {
            self.render(buffer)?;
        }
        Ok(())
    }

    fn set_panel_size(&mut self, id: &str, side: plugin::PanelSide, requested_size: usize) -> bool {
        let Some((current_side, current_size)) = self.panel_manager.panel_layout(id) else {
            return false;
        };
        let target_is_vertical = matches!(side, plugin::PanelSide::Left | plugin::PanelSide::Right);
        let current_is_vertical = matches!(
            current_side,
            plugin::PanelSide::Left | plugin::PanelSide::Right
        );
        let reserved_on_axis = if target_is_vertical {
            self.panel_manager
                .reserved_left_width()
                .saturating_add(self.panel_manager.reserved_right_width())
        } else {
            self.panel_manager
                .reserved_top_height()
                .saturating_add(self.panel_manager.reserved_bottom_height())
        };
        let reserved_other = if current_is_vertical == target_is_vertical {
            reserved_on_axis.saturating_sub(current_size.saturating_add(1))
        } else {
            reserved_on_axis
        };
        let (terminal_extent, minimum_editor, minimum_panel) = if target_is_vertical {
            (
                usize::from(self.size.0),
                MIN_EDITOR_WINDOW_WIDTH,
                MIN_DOCKED_PANEL_WIDTH,
            )
        } else {
            (
                usize::from(self.size.1),
                MIN_EDITOR_WINDOW_HEIGHT,
                MIN_DOCKED_PANEL_HEIGHT,
            )
        };
        let maximum = terminal_extent
            .saturating_sub(minimum_editor)
            .saturating_sub(reserved_other)
            .saturating_sub(1);
        if maximum == 0 {
            return false;
        }
        let size = requested_size.clamp(minimum_panel.min(maximum), maximum);

        if !self.panel_manager.update_panel_layout(id, side, size) {
            return false;
        }
        self.persist_panel_layout(id);
        self.apply_panel_layout();
        self.sync_with_window();
        true
    }

    fn restore_panel_layout(&mut self, id: &str) {
        let workspace = get_workspace_path();
        let Some(layout) = self.preferences.panel_layout(&workspace, id).copied() else {
            return;
        };
        let size = layout.size_for(layout.side).or_else(|| {
            self.panel_manager
                .panel_default_layout(id)
                .map(|(_, size)| size)
        });
        if let Some(size) = size {
            self.panel_manager.restore_panel_layout(
                id,
                layout.side,
                size,
                layout.vertical_size,
                layout.horizontal_size,
            );
        }
    }

    fn persist_panel_layout(&mut self, id: &str) {
        let Some((side, _)) = self.panel_manager.panel_layout(id) else {
            return;
        };
        let layout = PanelLayoutPreference {
            side,
            vertical_size: self
                .panel_manager
                .panel_preferred_size(id, plugin::PanelSide::Left),
            horizontal_size: self
                .panel_manager
                .panel_preferred_size(id, plugin::PanelSide::Top),
        };
        if let Err(error) = self
            .preferences
            .set_panel_layout(&get_workspace_path(), id, layout)
        {
            log!("failed to save panel layout for {id:?}: {error}");
        }
    }

    fn reset_panel_layout_preferences(&mut self, panel_id: Option<&str>) -> bool {
        let workspace = get_workspace_path();
        let preference_changed = if let Some(panel_id) = panel_id {
            self.preferences.remove_panel_layout(&workspace, panel_id)
        } else {
            self.preferences.clear_panel_layouts(&workspace)
        };
        let preference_changed = match preference_changed {
            Ok(changed) => changed,
            Err(error) => {
                log!("failed to reset panel layout preferences: {error}");
                self.set_legacy_message(Some(format!(
                    "unable to save panel layout reset: {error}"
                )));
                false
            }
        };

        let panel_ids = panel_id.map_or_else(
            || self.panel_manager.panel_ids(),
            |panel_id| vec![panel_id.to_string()],
        );
        let mut live_changed = false;
        let mut live_found = false;
        for panel_id in panel_ids {
            if self.panel_manager.panel_layout(&panel_id).is_some() {
                live_found = true;
                live_changed |= self.panel_manager.reset_panel_layout(&panel_id);
            }
        }
        if let Some(panel_id) = panel_id.filter(|_| !live_found && !preference_changed) {
            self.set_legacy_message(Some(format!("unknown panel {panel_id:?}")));
        }
        if live_changed {
            self.apply_panel_layout();
            self.sync_with_window();
        }
        live_changed || preference_changed
    }

    fn divider_resize_target_at_position(&self, x: usize, y: usize) -> Option<DividerResizeTarget> {
        if let Some(divider) = self.panel_manager.panel_divider_at_position(
            x,
            y,
            usize::from(self.size.0),
            usize::from(self.size.1),
        ) {
            return Some(DividerResizeTarget::Panel {
                id: divider.id,
                side: divider.side,
            });
        }

        self.window_manager
            .divider_at_position(x, y)
            .map(|divider| DividerResizeTarget::Window { divider })
    }

    fn divider_resize_target_on_window_edge(
        &self,
        position: Point,
        size: (usize, usize),
        vertical: bool,
        positive_edge: bool,
    ) -> Option<DividerResizeTarget> {
        if vertical {
            let x = if positive_edge {
                position.x.saturating_add(size.0)
            } else {
                position.x.checked_sub(1)?
            };
            let end = position.y.saturating_add(size.1);
            (position.y..end).find_map(|y| {
                self.divider_resize_target_at_position(x, y)
                    .filter(|target| target.is_vertical())
            })
        } else {
            let y = if positive_edge {
                position.y.saturating_add(size.1)
            } else {
                position.y.checked_sub(1)?
            };
            let end = position.x.saturating_add(size.0);
            (position.x..end).find_map(|x| {
                self.divider_resize_target_at_position(x, y)
                    .filter(|target| !target.is_vertical())
            })
        }
    }

    fn focused_pane_resize_targets(&self) -> PaneResizeMode {
        if let Some(panel_id) = self.panel_manager.focused_panel_id() {
            let Some((side, _)) = self.panel_manager.panel_layout(panel_id) else {
                return PaneResizeMode::default();
            };
            let target = DividerResizeTarget::Panel {
                id: panel_id.to_string(),
                side,
            };
            return if target.is_vertical() {
                PaneResizeMode {
                    vertical: Some(target),
                    horizontal: None,
                }
            } else {
                PaneResizeMode {
                    vertical: None,
                    horizontal: Some(target),
                }
            };
        }

        let Some(window) = self.window_manager.active_window() else {
            return PaneResizeMode::default();
        };
        let resolve = |vertical| {
            self.divider_resize_target_on_window_edge(
                window.position,
                window.size,
                vertical,
                /*positive_edge*/ true,
            )
            .or_else(|| {
                self.divider_resize_target_on_window_edge(
                    window.position,
                    window.size,
                    vertical,
                    /*positive_edge*/ false,
                )
            })
        };
        PaneResizeMode {
            vertical: resolve(true),
            horizontal: resolve(false),
        }
    }

    fn move_divider_target_by(&mut self, target: &DividerResizeTarget, delta: isize) -> bool {
        if delta == 0 {
            return false;
        }

        match target {
            DividerResizeTarget::Panel { id, side } => {
                let Some((_, current_size)) = self.panel_manager.panel_layout(id) else {
                    return false;
                };
                let size_delta =
                    if matches!(side, plugin::PanelSide::Right | plugin::PanelSide::Bottom) {
                        delta.saturating_neg()
                    } else {
                        delta
                    };
                self.set_panel_size(id, *side, current_size.saturating_add_signed(size_delta))
            }
            DividerResizeTarget::Window { divider } => {
                self.sync_to_window();
                let Some(span) = self.window_manager.divider_span(divider) else {
                    return false;
                };
                let position = span.moved_by(delta);
                let resized = self
                    .window_manager
                    .resize_divider(divider, position.x, position.y);
                if resized {
                    self.sync_with_window();
                }
                resized
            }
        }
    }

    fn move_captured_pane_divider(
        &mut self,
        direction: crate::window::Direction,
        amount: usize,
    ) -> bool {
        let amount = isize::try_from(amount).unwrap_or(isize::MAX);
        let (vertical, delta) = match direction {
            crate::window::Direction::Left => (true, amount.saturating_neg()),
            crate::window::Direction::Right => (true, amount),
            crate::window::Direction::Up => (false, amount.saturating_neg()),
            crate::window::Direction::Down => (false, amount),
        };
        let target = self.pane_resize_mode.as_ref().and_then(|mode| {
            if vertical {
                mode.vertical.clone()
            } else {
                mode.horizontal.clone()
            }
        });
        target.is_some_and(|target| self.move_divider_target_by(&target, delta))
    }

    fn resize_window_or_panel(
        &mut self,
        direction: crate::window::Direction,
        amount: usize,
    ) -> bool {
        let Some(panel_id) = self.panel_manager.focused_panel_id().map(str::to_string) else {
            return self.update_window_layout(|windows| {
                windows
                    .resize_window_by_cells(direction, amount)
                    .then_some(())
            });
        };
        let Some((side, current_size)) = self.panel_manager.panel_layout(&panel_id) else {
            return false;
        };
        let requested_size = match (side, direction) {
            (
                plugin::PanelSide::Left | plugin::PanelSide::Right,
                crate::window::Direction::Right,
            )
            | (
                plugin::PanelSide::Top | plugin::PanelSide::Bottom,
                crate::window::Direction::Down,
            ) => current_size.saturating_add(amount),
            (
                plugin::PanelSide::Left | plugin::PanelSide::Right,
                crate::window::Direction::Left,
            )
            | (plugin::PanelSide::Top | plugin::PanelSide::Bottom, crate::window::Direction::Up) => {
                current_size.saturating_sub(amount)
            }
            _ => return false,
        };
        self.set_panel_size(&panel_id, side, requested_size)
    }

    fn balance_focused_window_or_panel(&mut self) -> bool {
        let Some(panel_id) = self.panel_manager.focused_panel_id().map(str::to_string) else {
            return self.update_window_layout(WindowManager::balance_windows);
        };
        let Some((side, _)) = self.panel_manager.panel_layout(&panel_id) else {
            return false;
        };
        let Some(default_size) = self.panel_manager.panel_default_size(&panel_id, side) else {
            return false;
        };
        self.set_panel_size(&panel_id, side, default_size)
    }

    fn update_window_layout(
        &mut self,
        update: impl FnOnce(&mut WindowManager) -> Option<()>,
    ) -> bool {
        self.clear_pane_zoom();
        self.sync_to_window();
        let previous_windows = self
            .window_manager
            .windows()
            .into_iter()
            .map(|window| window.id)
            .collect::<HashSet<_>>();
        let previous_buffer = self.current_buffer().id();
        let previous_inline = self.active_inline_comment();
        if update(&mut self.window_manager).is_some() {
            self.sync_with_window();
            self.inline_comment_selections
                .retain(|(window, buffer), _| {
                    self.window_manager.window(*window).is_some()
                        && self
                            .buffer_manager
                            .iter()
                            .any(|candidate| candidate.id() == *buffer)
                });
            if self.current_buffer().id() == previous_buffer
                && self
                    .window_manager
                    .active_stable_window_id()
                    .is_some_and(|window| !previous_windows.contains(&window))
            {
                self.set_active_inline_comment(previous_inline);
            }
            true
        } else {
            false
        }
    }

    fn clear_pane_zoom(&mut self) -> bool {
        if self.zoomed_pane.take().is_none() {
            return false;
        }
        self.divider_drag = None;
        self.pane_resize_mode = None;
        self.apply_panel_layout();
        self.force_full_redraw = true;
        true
    }

    fn toggle_pane_zoom(&mut self) {
        if self.clear_pane_zoom() {
            return;
        }
        let Some(target) = self.current_focus_target() else {
            return;
        };
        if matches!(target, FocusTarget::Window(_)) && self.focus_ring().len() <= 1 {
            return;
        }
        self.zoomed_pane = Some(target);
        self.divider_drag = None;
        self.pane_resize_mode = None;
        self.apply_panel_layout();
        self.force_full_redraw = true;
    }

    fn clear_replaced_panel_zoom(&mut self, id: &str) {
        if matches!(&self.zoomed_pane, Some(FocusTarget::Panel(target)) if target == id) {
            self.clear_pane_zoom();
        }
    }

    fn configure_pane_presentation(&mut self, terminal_size: (usize, usize)) {
        let valid = self.zoomed_pane.as_ref().is_none_or(|target| {
            self.current_focus_target().as_ref() == Some(target)
                && match target {
                    FocusTarget::Window(id) => self.window_manager.window(*id).is_some(),
                    FocusTarget::Panel(id) => self.panel_manager.is_visible(id),
                }
        });
        if !valid {
            self.zoomed_pane = None;
            self.divider_drag = None;
            self.pane_resize_mode = None;
            self.force_full_redraw = true;
        }
        let (windows, panels) = match &self.zoomed_pane {
            Some(FocusTarget::Window(id)) => (
                WindowPresentation::Zoomed(*id),
                plugin::panel::PanelPresentation::Hidden,
            ),
            Some(FocusTarget::Panel(id)) => (
                WindowPresentation::Hidden,
                plugin::panel::PanelPresentation::Zoomed {
                    id: id.clone(),
                    size: (terminal_size.0, terminal_size.1.saturating_sub(2)),
                },
            ),
            None => (
                WindowPresentation::All,
                plugin::panel::PanelPresentation::Docked,
            ),
        };
        self.window_manager.set_presentation(windows);
        self.panel_manager.set_presentation(panels);
    }

    fn resize_window_layout(&mut self, terminal_size: (usize, usize)) {
        if self.resize_learn_layout(terminal_size) {
            return;
        }
        self.sync_to_window();
        self.configure_pane_presentation(terminal_size);
        let (reserved_left, reserved_right) = self.reserved_panel_widths(terminal_size.0);
        let (reserved_top, reserved_bottom) = self.reserved_panel_heights(terminal_size.1);
        self.window_manager.resize_with_origin(
            Point::new(reserved_left, reserved_top),
            (
                terminal_size
                    .0
                    .saturating_sub(reserved_left)
                    .saturating_sub(reserved_right),
                terminal_size
                    .1
                    .saturating_sub(reserved_top)
                    .saturating_sub(reserved_bottom),
            ),
        );
        self.sync_with_window();
    }

    fn resize_terminal_surface(&mut self, width: u16, height: u16, buffer: &mut RenderBuffer) {
        self.size = (width, height);
        self.divider_drag = None;
        self.pane_resize_mode = None;
        self.resize_window_layout((width as usize, height as usize));

        // A smaller viewport must scroll to the cursor, not move the cursor
        // to an earlier buffer line. Preserve inactive split positions too.
        for window in self.window_manager.windows_mut() {
            let cursor_line = window.vtop.saturating_add(window.cy);
            let height = window
                .inner_height()
                .saturating_sub(self.window_bar_manager.reserved_top_height(window.id));
            let cursor_row = window.cy.min(height.saturating_sub(1));
            if cursor_row != window.cy {
                window.vtop = cursor_line.saturating_sub(cursor_row);
                window.cy = cursor_row;
                window.skipcol = 0;
            }
        }
        self.sync_with_window();
        self.invalidate_terminal_render_state(buffer);

        let viewport_width = self.vwidth();
        let viewport_height = if self.inline_history_browser.is_some()
            || self
                .current_dialog
                .as_ref()
                .is_some_and(|dialog| dialog.uses_full_editor_viewport())
        {
            self.inline_history_viewport_height()
        } else {
            self.vheight()
        };
        let overlay_layout = self
            .current_dialog
            .as_ref()
            .and_then(|dialog| dialog.inline_comment_id())
            .and_then(|id| self.inline_comment_overlay_layout(id))
            .or_else(|| self.inline_assist_overlay_layout());
        let dialog_resized = if let Some(dialog) = &mut self.current_dialog {
            match overlay_layout {
                Some(layout) => dialog.update_overlay_layout(layout),
                None => dialog.resize(viewport_width, viewport_height),
            }
        } else {
            false
        };
        if self.current_dialog.is_some() && !dialog_resized {
            self.current_dialog = None;
        }
    }

    fn apply_panel_layout(&mut self) {
        self.resize_window_layout((usize::from(self.size.0), usize::from(self.size.1)));
    }

    fn reserved_panel_widths(&self, terminal_width: usize) -> (usize, usize) {
        if matches!(self.zoomed_pane, Some(FocusTarget::Window(_))) {
            return (0, 0);
        }
        let max_reserved = terminal_width.saturating_sub(MIN_EDITOR_WINDOW_WIDTH);
        let reserved_left = self.panel_manager.reserved_left_width().min(max_reserved);
        let reserved_right = self
            .panel_manager
            .reserved_right_width()
            .min(max_reserved.saturating_sub(reserved_left));
        (reserved_left, reserved_right)
    }

    fn reserved_panel_heights(&self, terminal_height: usize) -> (usize, usize) {
        if matches!(self.zoomed_pane, Some(FocusTarget::Window(_))) {
            return (0, 0);
        }
        let max_reserved = terminal_height.saturating_sub(MIN_EDITOR_WINDOW_HEIGHT);
        let reserved_top = self.panel_manager.reserved_top_height().min(max_reserved);
        let reserved_bottom = self
            .panel_manager
            .reserved_bottom_height()
            .min(max_reserved.saturating_sub(reserved_top));
        (reserved_top, reserved_bottom)
    }

    fn indentation(&self) -> Indentation {
        self.indentation_for_buffer_index(self.buffer_manager.active_index())
    }

    fn configured_indentation(config: &Config) -> HashMap<String, Indentation> {
        let mut indentation = HashMap::from_iter(
            [
                ("rs", 4),
                ("js", 2),
                ("jsx", 2),
                ("mjs", 2),
                ("cjs", 2),
                ("ts", 2),
                ("tsx", 2),
                ("json", 2),
                ("jsonc", 2),
                ("toml", 2),
                ("yaml", 2),
                ("yml", 2),
                ("sh", 2),
                ("bash", 2),
                ("zsh", 2),
                ("fish", 4),
            ]
            .map(|(file_type, shift_width)| {
                (
                    file_type.to_string(),
                    Indentation::new(shift_width, shift_width, true),
                )
            }),
        );
        for (language, definition) in &config.languages {
            if let Some(width) = definition.indent_width {
                let settings = Indentation::new(width, width, true);
                indentation.insert(language.clone(), settings);
                for extension in &definition.extensions {
                    indentation.insert(extension.trim_start_matches('.').to_string(), settings);
                }
            }
        }
        indentation
    }

    fn indentation_for_buffer_index(&self, buffer_index: usize) -> Indentation {
        if let Some(language) = self.highlight_language_id_for_buffer_index(buffer_index) {
            if let Some(indentation) = self.indentation.get(&language) {
                return *indentation;
            }
        }
        let file_type = self
            .buffer_manager
            .get(buffer_index)
            .and_then(|buffer| buffer.file_type());

        let Some(file_type) = file_type.as_deref() else {
            return Indentation::new(4, 4, true);
        };

        self.indentation
            .get(file_type)
            .copied()
            .unwrap_or_else(|| Indentation::new(4, 4, true))
    }

    fn tab_width_for_buffer_index(&self, buffer_index: usize) -> usize {
        self.indentation_for_buffer_index(buffer_index)
            .tab_width
            .max(1)
    }

    fn active_tab_width(&self) -> usize {
        self.tab_width_for_buffer_index(self.buffer_manager.active_index())
    }

    fn relative_line_numbers_enabled(&self) -> bool {
        self.config.relative_line_numbers.unwrap_or(false)
    }

    fn break_indent_options_for_buffer_index(&self, buffer_index: usize) -> BreakIndentOptions {
        BreakIndentOptions {
            enabled: self.config.breakindent.unwrap_or(true),
            tab_width: self
                .indentation_for_buffer_index(buffer_index)
                .tab_width
                .max(1),
        }
    }

    pub fn vwidth(&self) -> usize {
        self.size.0 as usize
    }

    pub fn vheight(&self) -> usize {
        self.window_manager
            .active_window()
            .map(|window| self.window_content_height(window))
            .unwrap_or_else(|| (self.size.1 as usize).saturating_sub(2))
    }

    pub(crate) fn inline_history_viewport_height(&self) -> usize {
        usize::from(self.size.1).saturating_sub(2)
    }

    pub(crate) fn picker_input_position(&self) -> crate::config::PickerInputPosition {
        self.config.picker.input_position
    }

    /// Returns the immutable language snapshot shared by editor-owned render surfaces.
    pub(crate) fn language_registry(&self) -> Arc<LanguageRegistry> {
        self.highlighter.registry()
    }

    pub(crate) fn picker_icons(&self) -> crate::config::PickerIconsConfig {
        self.config.picker.icons
    }

    pub(crate) fn statusline_config(&self) -> &StatuslineConfig {
        &self.config.statusline
    }

    /// Window-aware coordinate transformation methods
    /// Convert window-local X coordinate to terminal X coordinate
    pub fn window_to_terminal_x(&self, window: &crate::window::Window, x: usize) -> usize {
        window.position.x + x
    }

    /// Convert window-local Y coordinate to terminal Y coordinate
    pub fn window_to_terminal_y(&self, window: &crate::window::Window, y: usize) -> usize {
        window.position.y + self.window_content_top(window) + y
    }

    /// Convert buffer coordinates to window-local coordinates, accounting for viewport
    pub fn buffer_to_window_coords(
        &self,
        window: &crate::window::Window,
        buf_x: usize,
        buf_y: usize,
    ) -> Option<(usize, usize)> {
        let line = self.buffer_manager.get(window.buffer_index)?.get(buf_y)?;
        let display_col = grapheme_to_column_with_tabs(
            line.trim_end_matches('\n'),
            buf_x,
            self.tab_width_for_buffer_index(window.buffer_index),
        );
        let layout = self.layout_for_window(window);
        let segment = layout.segment_for_cursor(buf_y, display_col)?;
        Some((
            self.gutter_width_for_window(window)
                + 1
                + segment
                    .screen_col_for_display_col(display_col, self.window_content_width(window)),
            segment.row,
        ))
    }

    /// Get the effective viewport width for a window
    pub fn window_vwidth(&self, window: &crate::window::Window) -> usize {
        window.inner_width()
    }

    /// Get the effective viewport height for a window
    pub fn window_vheight(&self, window: &crate::window::Window) -> usize {
        self.window_content_height(window)
    }

    fn window_content_top(&self, window: &crate::window::Window) -> usize {
        self.window_bar_manager.reserved_top_height(window.id)
    }

    fn window_content_height(&self, window: &crate::window::Window) -> usize {
        window
            .inner_height()
            .saturating_sub(self.window_content_top(window))
    }

    fn window_content_width(&self, window: &crate::window::Window) -> usize {
        let gutter_width = self.gutter_width_for_window(window);
        window.inner_width().saturating_sub(gutter_width + 1)
    }

    fn layout_for_window(&self, window: &crate::window::Window) -> std::sync::Arc<DisplayLayout> {
        let Some(buffer) = self.buffer_manager.get(window.buffer_index) else {
            return std::sync::Arc::new(DisplayLayout::default());
        };
        let mut line_count = buffer.navigable_line_count();
        let mut line_count_override = None;
        if window.active && self.is_insert() {
            line_count_override = Some(self.buffer_line() + 1);
            line_count = line_count.max(self.buffer_line() + 1);
        }

        let break_indent = self.break_indent_options_for_buffer_index(window.buffer_index);
        let prediction = self
            .visible_inline_suggestion()
            .filter(|suggestion| window.active && suggestion.snapshot.buffer_id == buffer.id());
        let key = LayoutCacheKey {
            inline_selection: self.inline_comment_selection(window.id, buffer.id()),
            buffer_index: window.buffer_index,
            buffer_id: buffer.id(),
            revision: buffer.revision(),
            file: buffer.file.clone(),
            vtop: window.vtop,
            vleft: window.vleft,
            skipcol: window.skipcol,
            wrap: window.wrap,
            content_width: self.window_content_width(window),
            content_height: self.window_content_height(window),
            line_count_override,
            break_indent,
            inline_prediction: prediction.map(|suggestion| suggestion.snapshot.generation),
        };
        if let Some(layout) = self.layout_cache.borrow().get(&key) {
            return layout.clone();
        }

        let _span = perf::PerfSpan::start("layout_for_window:miss");
        let end = window
            .vtop
            .saturating_add(self.window_content_height(window))
            .min(line_count);
        let lines = (window.vtop..end)
            .filter_map(|line| buffer.get(line))
            .collect::<Vec<_>>();

        let comment_messages = self.inline_comment_display_messages_for_window(window.id, buffer);
        let comments = comment_messages
            .iter()
            .map(|(line, message)| (*line, message.as_str()))
            .collect::<Vec<_>>();
        let layout_config = LayoutConfig {
            content_width: self.window_content_width(window),
            height: self.window_content_height(window),
            wrap: window.wrap,
            vtop: window.vtop,
            vleft: window.vleft,
            skipcol: window.skipcol,
            break_indent,
        };
        let mut layout = layout_lines(&lines, line_count, layout_config).with_inline_comments(
            &comments,
            self.window_content_width(window),
            self.window_content_height(window),
        );
        if let Some(suggestion) = prediction {
            if let Some(line) = buffer.get(suggestion.snapshot.cursor.line) {
                let line = trim_line_ending(&line);
                let cursor_byte = line
                    .char_indices()
                    .nth(suggestion.snapshot.cursor.character)
                    .map_or(line.len(), |(byte, _)| byte);
                layout = layout.with_inline_prediction(
                    suggestion.snapshot.cursor.line,
                    line,
                    cursor_byte,
                    &suggestion.insertion,
                    layout_config,
                );
            }
        }
        let layout = std::sync::Arc::new(layout);

        let mut cache = self.layout_cache.borrow_mut();
        if cache.len() >= 32 {
            cache.clear();
        }
        cache.insert(key, layout.clone());
        layout
    }

    fn plugin_viewport_layout_payload(&self) -> Value {
        let Some(window) = self.active_window_with_editor_view() else {
            return json!({
                "buffer_index": self.buffer_manager.active_index(),
                "window_id": self.window_manager.active_stable_window_id().map(|id| id.0),
                "rows": [],
            });
        };
        let layout = self.layout_for_window(&window);
        let buffer = &self.buffer_manager[window.buffer_index];
        let gutter_width = self.gutter_width_for_window(&window);
        let content_start = gutter_width + 1;
        let content_width = self.window_content_width(&window);
        let indentation = self.indentation();
        let mut indentation_key = String::with_capacity(layout.rows.len() * 8);
        let rows = layout
            .rows
            .iter()
            .map(|segment| {
                let text = if !segment.first_segment {
                    String::new()
                } else if buffer.line_range_byte_len(segment.line, segment.line + 1)
                    > MAX_HIGHLIGHT_SLICE_BYTES
                {
                    buffer.line_prefix_contents(segment.line, MAX_PLUGIN_VIEWPORT_LINE_CHARS)
                } else {
                    buffer.get(segment.line).unwrap_or_default()
                };
                let text = text.trim_end_matches(['\r', '\n']);
                let indent_width =
                    leading_whitespace_display_width(text, indentation.tab_width.max(1));
                if segment.first_segment {
                    append_viewport_indentation_key(
                        &mut indentation_key,
                        segment.line,
                        indent_width,
                        text,
                    );
                }
                json!({
                    "screen_row": segment.row,
                    "line": segment.line,
                    "start_col": segment.start_col,
                    "end_col": segment.end_col,
                    "start_grapheme": segment.start_grapheme,
                    "end_grapheme": segment.end_grapheme,
                    "first_segment": segment.first_segment,
                    "indent_width": indent_width,
                    "visual_offset": segment.visual_offset,
                    "text": text,
                })
            })
            .collect::<Vec<_>>();

        json!({
            "buffer_index": window.buffer_index,
            "window_id": window.id.0,
            "width": window.inner_width(),
            "height": self.window_content_height(&window),
            "content_top": self.window_content_top(&window),
            "content_start": content_start,
            "content_width": content_width,
            "vtop": window.vtop,
            "vleft": window.vleft,
            "skipcol": window.skipcol,
            "wrap": window.wrap,
            "cursor": {
                "x": window.cx,
                "y": window.vtop + window.cy,
                "lsp_character": self.lsp_character_for_cursor(window.buffer_index, window.vtop + window.cy, window.cx),
                "screen_row": window.cy,
            },
            "indentation": {
                "shift_width": indentation.shift_width,
                "tab_width": indentation.tab_width,
            },
            "indentation_key": indentation_key,
            "line_count": buffer.navigable_line_count(),
            "revision": buffer.revision(),
            "file": buffer.file,
            "rows": rows,
        })
    }

    pub(crate) fn refresh_plugin_snapshots(
        &self,
        runtime: &mut Runtime,
        viewport: bool,
        windows: bool,
        editor_info: bool,
    ) -> anyhow::Result<()> {
        if viewport {
            runtime.set_snapshot("viewport_layout", self.plugin_viewport_layout_payload());
        }
        if windows {
            runtime.set_snapshot("windows", self.plugin_windows_payload());
        }
        if editor_info {
            runtime.set_snapshot("editor_info", serde_json::to_value(self.info())?);
        }
        Ok(())
    }

    fn plugin_windows_payload(&self) -> Value {
        let active_id = self.window_manager.active_stable_window_id();
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        let home = std::env::home_dir();
        let windows = self
            .window_manager
            .windows()
            .into_iter()
            .filter_map(|window| {
                let buffer = self.buffer_manager.get(window.buffer_index)?;
                let cursor_y = window.vtop + window.cy;
                let lsp_character =
                    self.lsp_character_for_cursor(window.buffer_index, cursor_y, window.cx);
                let content_top = self.window_content_top(window);
                let content_width = self.window_content_width(window);
                let content_height = self.window_content_height(window);
                Some(json!({
                    "id": window.id.0,
                    "window_id": window.id.0,
                    "active": Some(window.id) == active_id,
                    "buffer_index": window.buffer_index,
                    "document_id": buffer.id(),
                    "buffer_path": buffer.file,
                    "breadcrumb_components": buffer.file.as_deref().map(|file| {
                        crate::utils::breadcrumb_path_components(Path::new(file), &cwd, home.as_deref())
                    }).unwrap_or_default(),
                    "file": buffer.file,
                    "name": buffer.name(),
                    "revision": buffer.revision(),
                    "bounds": {
                        "x": window.position.x,
                        "y": window.position.y,
                        "width": window.inner_width(),
                        "height": window.inner_height(),
                    },
                    "content_bounds": {
                        "x": window.position.x,
                        "y": window.position.y + content_top,
                        "width": content_width,
                        "height": content_height,
                    },
                    "x": window.position.x,
                    "y": window.position.y,
                    "width": window.inner_width(),
                    "height": window.inner_height(),
                    "content_top": content_top,
                    "content_width": content_width,
                    "content_height": content_height,
                    "vtop": window.vtop,
                    "vleft": window.vleft,
                    "viewport": {
                        "top": window.vtop,
                        "left": window.vleft,
                    },
                    "cursor": {
                        "x": window.cx,
                        "y": cursor_y,
                        "lsp_character": lsp_character,
                    },
                    "lsp_position": {
                        "line": cursor_y,
                        "character": lsp_character,
                    },
                }))
            })
            .collect::<Vec<_>>();
        json!({ "windows": windows })
    }

    fn lsp_character_for_cursor(
        &self,
        buffer_index: usize,
        line: usize,
        grapheme_index: usize,
    ) -> usize {
        let Some(buffer) = self.buffer_manager.get(buffer_index) else {
            return grapheme_index;
        };
        if buffer.is_ascii() {
            let contents = buffer.contents_snapshot();
            let Some(text) = contents.get_line(line) else {
                return grapheme_index;
            };
            let length = text.len_chars();
            let character = grapheme_index.min(length);
            if character.saturating_add(1) == length
                && text.get_char(character) == Some('\n')
                && text.get_char(character.saturating_sub(1)) == Some('\r')
            {
                return length;
            }
            return character;
        }
        buffer
            .get(line)
            .map(|text| {
                text.graphemes(true)
                    .take(grapheme_index)
                    .flat_map(str::chars)
                    .map(char::len_utf16)
                    .sum()
            })
            .unwrap_or(grapheme_index)
    }

    fn active_content_width(&self) -> usize {
        self.window_manager
            .active_window()
            .map(|window| self.window_content_width(window))
            .unwrap_or_else(|| self.vwidth().saturating_sub(self.gutter_width() + 1))
    }

    fn sidescroll(&self) -> usize {
        self.config.sidescroll.unwrap_or(1).max(1)
    }

    fn sidescrolloff(&self, width: usize) -> usize {
        self.config
            .sidescrolloff
            .unwrap_or(0)
            .min(width.saturating_sub(1))
    }

    pub fn cursor_position(&self) -> (usize, usize) {
        (self.vx + self.cx, self.cy)
    }

    /// Returns the display width of the current line
    fn line_length(&self) -> usize {
        self.length_for_line(self.buffer_line())
    }

    fn grapheme_to_char_on_line(&self, x: usize, y: usize) -> usize {
        if x == 0 {
            return 0;
        }
        let buffer = self.current_buffer();
        if buffer.is_ascii() {
            let contents = buffer.contents_snapshot();
            return contents
                .get_line(y)
                .map(|line| {
                    let length = line.len_chars();
                    let newline = line.get_char(length.saturating_sub(1)) == Some('\n');
                    x.min(length.saturating_sub(usize::from(newline)))
                })
                .unwrap_or(x);
        }
        buffer
            .get(y)
            .map(|line| grapheme_to_char(line.trim_end_matches('\n'), x))
            .unwrap_or(x)
    }

    fn char_to_grapheme_on_line(&self, x: usize, y: usize) -> usize {
        let buffer = self.current_buffer();
        if buffer.is_ascii() {
            return self.grapheme_to_char_on_line(x, y);
        }
        buffer
            .get(y)
            .map(|line| char_to_grapheme(line.trim_end_matches('\n'), x))
            .unwrap_or(x)
    }

    fn next_word_search_char_on_line(&self, x: usize, y: usize) -> usize {
        let buffer = self.current_buffer();
        if buffer.is_ascii() {
            let contents = buffer.contents_snapshot();
            let Some(line) = contents.get_line(y) else {
                return x;
            };
            let length = line.len_chars();
            let newline = line.get_char(length.saturating_sub(1)) == Some('\n');
            let length = length.saturating_sub(usize::from(newline));
            return if x > 0 && x < length && line.get_char(x).is_some_and(char::is_whitespace) {
                x - 1
            } else {
                x.min(length)
            };
        }
        let Some(line) = buffer.get(y) else {
            return x;
        };
        let line = line.trim_end_matches('\n');
        if x > 0
            && line
                .graphemes(true)
                .nth(x)
                .is_some_and(|grapheme| grapheme.chars().all(char::is_whitespace))
        {
            grapheme_to_char(line, x - 1)
        } else {
            grapheme_to_char(line, x)
        }
    }

    /// Returns the display width of the current line in columns
    #[allow(dead_code)]
    fn line_display_width(&self) -> usize {
        if let Some(line) = self.viewport_line(self.cy) {
            let line = line.trim_end_matches('\n');
            return display_width_with_tabs(line, self.active_tab_width());
        }
        0
    }

    fn length_for_line(&self, n: usize) -> usize {
        let buffer = self.current_buffer();
        if buffer.is_ascii() {
            let contents = buffer.contents_snapshot();
            return contents
                .get_line(n)
                .map(|line| {
                    let length = line.len_chars();
                    let newline = line.get_char(length.saturating_sub(1)) == Some('\n');
                    length.saturating_sub(usize::from(newline))
                })
                .unwrap_or_default();
        }
        if let Some(line) = buffer.get(n) {
            let line = line.trim_end_matches('\n');
            return grapheme_len(line);
        }
        0
    }

    fn last_cell_for_line(&self, n: usize) -> usize {
        self.length_for_line(n).saturating_sub(1)
    }

    /// Returns the current buffer y position
    fn buffer_line(&self) -> usize {
        self.vtop + self.cy
    }

    /// Returns the buffer URI
    fn buffer_uri(&self) -> anyhow::Result<Option<String>> {
        self.current_buffer().uri()
    }

    fn viewport_line(&self, n: usize) -> Option<String> {
        let buffer_line = self.vtop + n;
        self.current_buffer().get(buffer_line)
    }

    fn gutter_width(&self) -> usize {
        let buffer_index = self.buffer_manager.active_index();
        let window_width = self
            .window_manager
            .active_window()
            .map_or(self.vwidth(), |window| window.inner_width());
        self.gutter_width_for_buffer_index(buffer_index)
            + self.inline_comment_lane_width_for_buffer(buffer_index, window_width)
    }

    /// Sign and line-number columns, excluding the annotation lane and separator.
    fn gutter_width_for_buffer_index(&self, buffer_index: usize) -> usize {
        self.buffer_manager
            .get(buffer_index)
            .map(|buffer| {
                GUTTER_SIGN_COLUMN_WIDTH + buffer.len().saturating_add(1).to_string().len()
            })
            .unwrap_or(GUTTER_SIGN_COLUMN_WIDTH)
    }

    fn line_number_width_for_window(&self, window: &crate::window::Window) -> usize {
        self.gutter_width_for_buffer_index(window.buffer_index)
            .saturating_sub(GUTTER_SIGN_COLUMN_WIDTH)
    }

    fn gutter_width_for_window(&self, window: &crate::window::Window) -> usize {
        self.gutter_width_for_buffer_index(window.buffer_index)
            + self.inline_comment_lane_width(window)
    }

    pub fn highlight(&mut self, file: Option<&str>, code: &str) -> anyhow::Result<Vec<StyleInfo>> {
        self.highlighter.highlight_for_file(file, code)
    }

    fn highlight_spans_for_language(
        &mut self,
        language_id: Option<&str>,
        code: &str,
    ) -> anyhow::Result<Vec<HighlightSpan>> {
        let Some(language_id) = language_id else {
            return Ok(Vec::new());
        };
        self.highlighter
            .highlight(language_id, code)
            .map(style_info_to_highlight_spans)
    }

    fn highlight_language_id_for_buffer_index(&self, buffer_index: usize) -> Option<String> {
        let buffer = self.buffer_manager.get(buffer_index)?;
        match buffer.syntax_selection() {
            SyntaxSelection::Auto => self
                .highlighter
                .language_id_for_file(buffer.file.as_deref())
                .map(ToString::to_string),
            SyntaxSelection::Off => None,
            SyntaxSelection::Language(language) => self
                .highlighter
                .language_id_for_name(language)
                .map(ToString::to_string),
        }
    }

    /// Returns highlight spans positioned relative to the viewport text
    /// (buffer lines `vtop..vtop + height` concatenated, as produced by
    /// `layout_lines`).
    ///
    /// Internally a larger slice (viewport plus margin) is parsed and cached
    /// per buffer, so scrolling line-by-line slices the cached spans instead
    /// of running tree-sitter on every scrolled line.
    fn viewport_highlight_spans(
        &mut self,
        buffer_index: usize,
        vtop: usize,
        height: usize,
    ) -> anyhow::Result<Vec<HighlightSpan>> {
        let Some(buffer) = self.buffer_manager.get(buffer_index) else {
            return Ok(Vec::new());
        };
        let buffer_id = buffer.id();
        let revision = buffer.revision();
        let file = buffer.file.clone();
        let language_id = self.highlight_language_id_for_buffer_index(buffer_index);
        let requires_document_prefix = self
            .highlighter
            .requires_document_prefix(language_id.as_deref());
        let line_count = buffer.len();
        if vtop >= line_count {
            return Ok(Vec::new());
        }
        let viewport_end = (vtop + height).min(line_count);

        let cached = self.highlight_cache.get(&buffer_index);
        let same_document = cached.is_some_and(|entry| {
            entry.buffer_id == buffer_id
                && entry.revision == revision
                && entry.file == file
                && entry.language_id == language_id
        });
        let covered = same_document
            && cached.is_some_and(|entry| {
                let parse_end = entry.start_line + entry.line_offsets.len().saturating_sub(1);
                entry.start_line <= vtop && parse_end >= viewport_end
            });

        if !covered {
            let _span = perf::PerfSpan::start("highlight:miss");
            // An edit invalidates the cache every keystroke, so keep the
            // margin small there; a same-document miss means scrolling, where
            // a screenful of margin makes held j/k mostly cache hits.
            let margin = if same_document || cached.is_none() {
                height
            } else {
                8
            };
            let mut parse_start = if requires_document_prefix {
                0
            } else {
                vtop.saturating_sub(margin)
            };
            if language_id.as_deref() == Some("markdown") {
                if let Some(fence_start) = Self::markdown_fence_start(buffer, vtop) {
                    parse_start = parse_start.min(fence_start);
                }
            }
            let mut parse_end = (vtop + height + margin).min(line_count);

            if buffer.line_range_byte_len(parse_start, parse_end) > MAX_HIGHLIGHT_SLICE_BYTES {
                parse_start = if requires_document_prefix { 0 } else { vtop };
                parse_end = viewport_end;
                if buffer.line_range_byte_len(parse_start, parse_end) > MAX_HIGHLIGHT_SLICE_BYTES {
                    self.highlight_cache.remove(&buffer_index);
                    return Ok(Vec::new());
                }
            }

            let (text, line_offsets) =
                buffer.line_range_contents_with_offsets(parse_start, parse_end);

            let spans = self.highlight_spans_for_language(language_id.as_deref(), &text)?;
            if self.highlight_cache.len() >= 32 {
                self.highlight_cache.clear();
            }
            self.highlight_cache.insert(
                buffer_index,
                ViewportHighlightEntry {
                    buffer_id,
                    revision,
                    file,
                    language_id,
                    start_line: parse_start,
                    line_offsets,
                    spans,
                },
            );
        }

        let entry = &self.highlight_cache[&buffer_index];
        let last_offset_index = entry.line_offsets.len() - 1;
        let start_byte = entry.line_offsets[(vtop - entry.start_line).min(last_offset_index)];
        let end_byte = entry.line_offsets[(viewport_end - entry.start_line).min(last_offset_index)];

        Ok(entry
            .spans
            .iter()
            .filter(|span| span.end > start_byte && span.start < end_byte)
            .map(|span| HighlightSpan {
                start: span.start.saturating_sub(start_byte),
                end: span.end - start_byte,
                order: span.order,
                priority: span.priority,
                style: span.style.clone(),
            })
            .collect())
    }

    fn markdown_fence_start(buffer: &Buffer, viewport_start: usize) -> Option<usize> {
        let mut inspected_bytes = 0_usize;
        for (offset, line) in buffer
            .preceding_lines(viewport_start)
            .take(MAX_MARKDOWN_FENCE_LOOKBACK_LINES)
            .enumerate()
        {
            inspected_bytes = inspected_bytes.saturating_add(line.len_bytes());
            if inspected_bytes > 64 * 1024 {
                return None;
            }
            let joined;
            let source = if let Some(source) = line.as_str() {
                source
            } else {
                joined = line.to_string();
                &joined
            };
            let trimmed = source.trim_end_matches(['\r', '\n']);
            let indentation = trimmed.len() - trimmed.trim_start_matches(' ').len();
            if indentation > 3 {
                continue;
            }
            let marker = &trimmed[indentation..];
            let Some(character @ ('`' | '~')) = marker.chars().next() else {
                continue;
            };
            let marker_length = marker
                .bytes()
                .take_while(|byte| *byte == character as u8)
                .count();
            if marker_length < 3 {
                continue;
            }
            let information = marker[marker_length..].trim();
            if information.is_empty() {
                return None;
            }
            if character == '`' && information.contains('`') {
                continue;
            }
            return Some(viewport_start - offset - 1);
        }
        None
    }

    pub fn draw_line_diagnostics(&mut self, buffer: &mut RenderBuffer, line_num: usize) {
        let fg = adjust_color_brightness(self.theme.style.fg, -20);
        let bg = adjust_color_brightness(self.theme.style.bg, 10);

        // TODO: take it from theme
        let hint_style = Style {
            fg,
            bg,
            italic: true,
            ..Default::default()
        };
        let Ok(Some(uri)) = self.buffer_uri() else {
            // TODO: log the error
            return;
        };
        let Some(line_diagnostics) = self.diagnostics.get(&uri) else {
            return;
        };
        let diagnostics = line_diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.range.start.line == line_num)
            .collect::<Vec<_>>();
        if diagnostics.is_empty() {
            return;
        }

        let Some(line) = self.current_buffer().get(line_num) else {
            return;
        };

        let x = self.gutter_width()
            + display_width_with_tabs(line.trim_end_matches('\n'), self.active_tab_width())
            + 5;

        // otherwise, clear the line
        let text = " ".repeat(self.vwidth().saturating_sub(x));
        buffer.set_text(x, line_num - self.vtop, &text, &self.theme.style);

        let prefix = "■".repeat(diagnostics.len());
        let msg = diagnostics[0].message.replace("\n", " ");
        let msg = format!("{} {}", prefix, msg);
        buffer.set_text(x, line_num - self.vtop, &msg, &hint_style);
    }

