    fn inline_test_editor(contents: &str) -> Editor {
        let config = Config::default();
        Editor::with_size(
            Box::new(crate::lsp::LspManager::new(config.lsp.clone())),
            60,
            12,
            config,
            Theme::default(),
            vec![Buffer::new(None, contents.to_string())],
        )
        .unwrap()
    }

    #[test]
    fn inline_assist_targets_the_current_line_or_exact_visual_selection() {
        let mut editor = inline_test_editor("alpha\nβeta\nomega\n");
        editor.cy = 1;
        let (line, scope) = editor.inline_assist_target().unwrap();
        assert_eq!(
            line,
            TextRange::new(TextPosition::new(1, 0), TextPosition::new(2, 0))
        );
        assert_eq!(editor.current_buffer().text_in_range(line), "βeta\n");
        assert_eq!(scope, "line 2");

        editor.mode = Mode::Visual;
        editor.selection = Some(Rect::new(1, 1, 2, 1));
        let (selection, scope) = editor.inline_assist_target().unwrap();
        assert_eq!(
            selection,
            TextRange::new(TextPosition::new(1, 1), TextPosition::new(1, 3))
        );
        assert_eq!(editor.current_buffer().text_in_range(selection), "et");
        assert_eq!(scope, "line 2 selection");

        editor.mode = Mode::VisualLine;
        editor.selection = Some(Rect::new(0, 0, 0, 1));
        let (lines, _) = editor.inline_assist_target().unwrap();
        assert_eq!(
            lines,
            TextRange::new(TextPosition::new(0, 0), TextPosition::new(2, 0))
        );
        assert_eq!(
            editor.current_buffer().text_in_range(lines),
            "alpha\nβeta\n"
        );

        editor.mode = Mode::VisualBlock;
        assert!(editor.inline_assist_target().is_err());
    }

    #[test]
    fn inline_assist_uses_only_the_enclosing_function_without_a_selection() {
        let source = "fn first() {\n    work();\n}\n\nfn second() {}\n";
        let mut editor = inline_test_editor(source);
        editor
            .current_buffer_mut()
            .set_syntax_selection(SyntaxSelection::Language("rust".into()));
        editor.cy = 1;
        let (range, scope) = editor.inline_assist_target().unwrap();
        assert_eq!(
            editor.current_buffer().text_in_range(range),
            "fn first() {\n    work();\n}\n"
        );
        assert_eq!(scope, "function · lines 1–3");
        editor.cy = 3;
        let (range, scope) = editor.inline_assist_target().unwrap();
        assert_eq!(editor.current_buffer().text_in_range(range), "\n");
        assert_eq!(scope, "line 4");
        editor.cy = 1;
        editor.mode = Mode::VisualLine;
        editor.selection = Some(Rect::new(0, 1, 0, 1));
        let (range, _) = editor.inline_assist_target().unwrap();
        assert_eq!(
            editor.current_buffer().text_in_range(range),
            "    work();\n"
        );

        let mut editor = inline_test_editor("fn first() {} fn second() {}\n");
        editor
            .current_buffer_mut()
            .set_syntax_selection(SyntaxSelection::Language("rust".into()));
        let (range, _) = editor.inline_assist_target().unwrap();
        assert_eq!(
            editor.current_buffer().text_in_range(range),
            "fn first() {}"
        );
    }

    #[test]
    fn inline_assist_layout_remains_owned_by_the_initiating_split() {
        let mut editor = inline_test_editor("alpha\nbeta\n");
        editor.window_manager.split_vertical(0).unwrap();
        editor.window_manager.set_active(1);
        editor.sync_with_window();
        let right_window = editor.window_manager.active_window().unwrap().clone();
        let range = TextRange::new(TextPosition::new(0, 0), TextPosition::new(1, 0));
        editor.inline_assist = Some(InlineAssistSession {
            parent_comment: None,
            allow_expansion: false,
            buffer_id: editor.current_buffer().id(),
            window_id: right_window.id,
            expected_revision: editor.current_buffer().revision(),
            range,
            expected_text: "alpha\n".to_string(),
            scope: "line 1".to_string(),
            request_id: None,
            session_id: None,
            transaction_id: None,
            annotation_group_id: "test-group".to_string(),
            has_result: false,
            result_request_id: None,
        });

        editor.window_manager.set_active(0);
        editor.sync_with_window();
        let layout = editor.inline_assist_overlay_layout().unwrap();

        assert_eq!(layout.viewport.x, right_window.position.x);
        assert_eq!(layout.viewport.width, right_window.inner_width());
        assert!(layout.anchor.0 >= right_window.position.x);
    }

    #[tokio::test]
    async fn inline_replacement_is_unsaved_attributed_and_undoable() {
        let mut editor = inline_test_editor("let x = 1;\nnext();\n");
        editor.test_disable_terminal_output();
        let range = TextRange::new(TextPosition::new(0, 0), TextPosition::new(1, 0));
        let window_id = editor.window_manager.active_stable_window_id().unwrap();
        editor.inline_assist = Some(InlineAssistSession {
            parent_comment: None,
            allow_expansion: false,
            buffer_id: editor.current_buffer().id(),
            window_id,
            expected_revision: editor.current_buffer().revision(),
            range,
            expected_text: "let x = 1;\n".to_string(),
            scope: "line 1".to_string(),
            request_id: Some("request-inline".to_string()),
            session_id: Some("session-inline".to_string()),
            transaction_id: None,
            annotation_group_id: "test-group".to_string(),
            has_result: false,
            result_request_id: None,
        });
        let mut render_buffer = RenderBuffer::new(60, 12, &Style::default());
        let mut runtime = Runtime::new();

        editor
            .apply_inline_result(
                "request-inline",
                "session-inline",
                &InlineAssistResult {
                    expanded_scope: None,
                    needs_agent: None,
                    replacement: Some("let answer = 1;\n".to_string()),
                    comments: Vec::new(),
                },
                &mut render_buffer,
                &mut runtime,
            )
            .await
            .unwrap();

        assert_eq!(
            editor.current_buffer().contents(),
            "let answer = 1;\nnext();\n"
        );
        assert!(editor.current_buffer().is_dirty());
        assert!(matches!(
            editor
                .current_buffer()
                .undo_history
                .latest_transaction()
                .map(|transaction| &transaction.origin),
            Some(EditOrigin::Agent { session_id, turn_id })
                if session_id == "session-inline" && turn_id == "request-inline"
        ));

        editor
            .execute(&Action::UndoInlineAssist, &mut render_buffer, &mut runtime)
            .await
            .unwrap();
        assert_eq!(editor.current_buffer().contents(), "let x = 1;\nnext();\n");
        assert!(!editor.current_buffer().is_dirty());
    }

    #[tokio::test]
    async fn inline_replacement_rejects_a_stale_buffer_without_mutating_it() {
        let mut editor = inline_test_editor("old\n");
        editor.test_disable_terminal_output();
        let range = TextRange::new(TextPosition::new(0, 0), TextPosition::new(1, 0));
        let revision = editor.current_buffer().revision();
        let window_id = editor.window_manager.active_stable_window_id().unwrap();
        editor.inline_assist = Some(InlineAssistSession {
            parent_comment: None,
            allow_expansion: false,
            buffer_id: editor.current_buffer().id(),
            window_id,
            expected_revision: revision,
            range,
            expected_text: "old\n".to_string(),
            scope: "line 1".to_string(),
            request_id: Some("stale-request".to_string()),
            session_id: Some("inline-session".to_string()),
            transaction_id: None,
            annotation_group_id: "test-group".to_string(),
            has_result: false,
            result_request_id: None,
        });
        editor.begin_transaction("concurrent edit");
        editor.replace_range(range, "newer\n");
        editor.commit_transaction(editor.cursor_snapshot());
        let mut render_buffer = RenderBuffer::new(60, 12, &Style::default());
        let mut runtime = Runtime::new();

        let error = editor
            .apply_inline_result(
                "stale-request",
                "inline-session",
                &InlineAssistResult {
                    expanded_scope: None,
                    needs_agent: None,
                    replacement: Some("model output\n".to_string()),
                    comments: Vec::new(),
                },
                &mut render_buffer,
                &mut runtime,
            )
            .await
            .unwrap_err();

        assert!(error.to_string().contains("buffer changed"));
        assert_eq!(editor.current_buffer().contents(), "newer\n");
    }

