    #[tokio::test]
    async fn colon_commands_dispatch_registered_plugins_and_preserve_builtin_precedence() {
        drain_plugin_requests();
        let mut editor = test_editor(/*width*/ 80, /*height*/ 10);
        let mut buffer =
            RenderBuffer::new(/*width*/ 80, /*height*/ 10, &Style::default());
        let mut runtime = Runtime::new();
        runtime
            .load_plugin(
                "colon_commands",
                r#"
                    pub fn activate() {
                        red::add_command("ExampleCommand", example);
                        red::add_command("wrap", shadow_builtin);
                    }

                    fn example() {
                        red::execute("Print", "hello from colon plugin");
                    }

                    fn shadow_builtin() {
                        red::execute("Print", "plugin shadowed built-in");
                    }
                "#,
            )
            .await
            .unwrap();

        enter_colon_command(&mut editor, &mut buffer, &mut runtime, "ExampleCommand").await;

        assert_eq!(
            editor.last_error.as_deref(),
            Some("hello from colon plugin")
        );
        assert!(render_text_rows(&buffer)[9].contains("hello from colon plugin"));

        editor.wrap = false;
        enter_colon_command(&mut editor, &mut buffer, &mut runtime, "wrap").await;

        assert!(editor.wrap);
        assert_ne!(
            editor.last_error.as_deref(),
            Some("plugin shadowed built-in")
        );
    }

    #[tokio::test]
    async fn set_relative_line_number_commands_update_and_repaint_the_gutter() {
        let config = Config::default();
        let lsp = Box::new(crate::lsp::LspManager::new(config.lsp.clone()));
        let content = (1..=120)
            .map(|line| format!("line {line}"))
            .collect::<Vec<_>>()
            .join("\n");
        let mut editor = Editor::with_size(
            lsp,
            40,
            10,
            config,
            Theme::default(),
            vec![Buffer::new(None, content)],
        )
        .unwrap();
        editor.test_disable_terminal_output();
        editor.vtop = 28;
        editor.cy = 3;
        let mut buffer = RenderBuffer::new(40, 10, &Style::default());
        let mut runtime = Runtime::new();

        enter_colon_command(&mut editor, &mut buffer, &mut runtime, "set relativenumber").await;

        assert!(editor.relative_line_numbers_enabled());
        let rows = render_text_rows(&buffer);
        assert_eq!(rows[2].chars().take(6).collect::<String>(), "    1 ");
        assert_eq!(rows[3].chars().take(6).collect::<String>(), "  32  ");

        enter_colon_command(
            &mut editor,
            &mut buffer,
            &mut runtime,
            "set norelativenumber",
        )
        .await;

        assert!(!editor.relative_line_numbers_enabled());
        let rows = render_text_rows(&buffer);
        assert_eq!(rows[2].chars().take(6).collect::<String>(), "   31 ");
        assert_eq!(rows[3].chars().take(6).collect::<String>(), "   32 ");
    }

