    #[test]
    fn git_status_index_rolls_up_directory_precedence() {
        let statuses = [
            ("src/nested/staged.rs", "staged"),
            ("src/nested/ignored.rs", "ignored"),
            ("src/nested/untracked.rs", "untracked"),
            ("src/nested/modified.rs", "modified"),
            ("src/nested/added.rs", "added"),
            ("src/nested/deleted.rs", "deleted"),
            ("src/nested/renamed.rs", "renamed"),
            ("src/nested/conflict.rs", "conflict"),
            ("vendor/cache.rs", "ignored"),
            ("mixed/modified.rs", "modified"),
            ("mixed/untracked.rs", "untracked"),
        ]
        .into_iter()
        .map(|(path, status)| {
            json!({
                "path": path,
                "absolute_path": format!("/repo/{path}"),
                "status": status,
            })
        })
        .chain([json!({
            "path": "outside.rs",
            "absolute_path": "/other/outside.rs",
            "status": "conflict",
        })])
        .collect::<Vec<_>>();

        let index = git_status_index(&statuses, "/repo/");

        assert!(index.get("/repo").is_none());
        assert_eq!(index["/repo/src"], "conflict");
        assert_eq!(index["/repo/src/nested"], "conflict");
        assert_eq!(index["/repo/src/nested/staged.rs"], "staged");
        assert_eq!(index["/repo/src/nested/renamed.rs"], "renamed");
        assert_eq!(index["/repo/vendor/cache.rs"], "ignored");
        assert!(index.get("/repo/vendor").is_none());
        assert_eq!(index["/repo/mixed"], "untracked");
        assert!(index.get("/other/outside.rs").is_none());
    }

    #[test]
    fn git_status_index_does_not_roll_ignored_files_up_to_tracked_directories() {
        let statuses = [
            ("src/.DS_Store", "/repo/src/.DS_Store"),
            ("src/lsp/.DS_Store", "/repo/src/lsp/.DS_Store"),
            ("target/", "/repo/target/"),
        ]
        .into_iter()
        .map(|(path, absolute_path)| {
            json!({
                "path": path,
                "absolute_path": absolute_path,
                "status": "ignored",
            })
        })
        .collect::<Vec<_>>();

        let index = git_status_index(&statuses, "/repo");

        assert_eq!(index["/repo/src/.DS_Store"], "ignored");
        assert_eq!(index["/repo/src/lsp/.DS_Store"], "ignored");
        assert_eq!(index["/repo/target"], "ignored");
        assert!(index.get("/repo").is_none());
        assert!(index.get("/repo/src").is_none());
        assert!(index.get("/repo/src/lsp").is_none());
        assert!(index.get("/repo/target/").is_none());
    }

    #[test]
    fn git_status_index_reuses_ancestors_without_hiding_later_conflicts() {
        let statuses = [
            ("src/nested/first.rs", "modified"),
            ("src/nested/second.rs", "modified"),
            ("src/nested/third.rs", "untracked"),
            ("src/nested/fourth.rs", "conflict"),
            ("src/nested/fifth.rs", "staged"),
        ]
        .into_iter()
        .map(|(path, status)| {
            json!({
                "path": path,
                "absolute_path": format!("/repo/{path}"),
                "status": status,
            })
        })
        .collect::<Vec<_>>();

        let index = git_status_index(&statuses, "/repo/");
        assert_eq!(index["/repo/src"], "conflict");
        assert_eq!(index["/repo/src/nested"], "conflict");
        assert_eq!(index["/repo/src/nested/first.rs"], "modified");
        assert_eq!(index["/repo/src/nested/third.rs"], "untracked");
        assert_eq!(index["/repo/src/nested/fourth.rs"], "conflict");
        assert_eq!(index["/repo/src/nested/fifth.rs"], "staged");
    }

