    #[tokio::test]
    async fn plugin_file_operations_reconcile_open_buffer_identity_without_losing_edits() {
        let root = tempfile::tempdir().unwrap();
        let old = root.path().join("old.rs");
        let renamed = root.path().join("nested/renamed.rs");
        let mut editor = lsp_test_editor(vec![Buffer::new(
            Some(old.to_string_lossy().into_owned()),
            "unsaved contents".to_string(),
        )]);
        editor.config.show_diagnostics = true;
        editor.config.diagnostics.icon_style = PickerIconStyle::Ascii;
        let old_uri = crate::lsp::file_uri(&old).unwrap();
        editor.add_diagnostics(
            Some(&old_uri),
            &[diagnostic_at(
                0,
                Some(DiagnosticSeverity::Warning),
                "warning",
            )],
        );
        editor.buffer_manager[0].dirty = true;

        editor
            .reconcile_plugin_file_operation(&plugin::filesystem::FileOperationOutcome {
                payload: Value::Null,
                renames: vec![(old, renamed.clone())],
                removals: Vec::new(),
            })
            .await
            .unwrap();

        assert_eq!(
            editor.buffer_manager[0].file.as_deref(),
            Some(renamed.to_str().unwrap())
        );
        assert_eq!(editor.buffer_manager[0].contents(), "unsaved contents");
        assert!(editor.buffer_manager[0].is_dirty());
        let renamed_uri = crate::lsp::file_uri(&renamed).unwrap();
        assert!(editor.diagnostics.contains_key(&renamed_uri));
        assert_eq!(
            editor
                .gutter_sign_manager
                .visible_sign(0, 0)
                .map(|sign| sign.text.as_str()),
            Some("W")
        );

        editor
            .reconcile_plugin_file_operation(&plugin::filesystem::FileOperationOutcome {
                payload: Value::Null,
                renames: Vec::new(),
                removals: vec![renamed],
            })
            .await
            .unwrap();

        assert!(editor.buffer_manager[0].file.is_none());
        assert_eq!(editor.buffer_manager[0].contents(), "unsaved contents");
        assert!(editor.buffer_manager[0].is_dirty());
        assert!(editor.gutter_sign_manager.visible_sign(0, 0).is_none());
        assert_eq!(
            editor.last_error.as_deref(),
            Some("Removed file kept open as an unsaved scratch buffer")
        );
    }

    fn lsp_edit(start: (usize, usize), end: (usize, usize), text: &str) -> LspTextEdit {
        LspTextEdit {
            range: Range {
                start: crate::lsp::Position {
                    line: start.0,
                    character: start.1,
                },
                end: crate::lsp::Position {
                    line: end.0,
                    character: end.1,
                },
            },
            new_text: text.to_string(),
        }
    }

    #[test]
    fn formatting_response_creates_revision_checked_workspace_edit() {
        let path = std::env::temp_dir().join("red format café #1.rs");
        let mut editor = lsp_test_editor(vec![Buffer::new(
            Some(path.to_string_lossy().into_owned()),
            "👋   value".to_string(),
        )]);
        let uri = editor.buffer_manager[0].uri().unwrap().unwrap();
        let revision = editor.buffer_manager[0].revision();
        editor.pending_lsp_edit_requests.insert(
            41,
            PendingLspEdit {
                buffer_id: editor.buffer_manager[0].id(),
                revision,
                uri: uri.clone(),
            },
        );
        let message = InboundMessage::Message(ResponseMessage {
            id: 41,
            result: serde_json::to_value(vec![lsp_edit((0, 2), (0, 5), " ")]).unwrap(),
            request: Some(crate::lsp::Request::new(
                "textDocument/formatting",
                serde_json::json!({ "textDocument": { "uri": uri } }),
            )),
        });

        let action =
            editor.handle_lsp_message(&message, Some("textDocument/formatting".to_string()));

        assert!(matches!(
            action,
            Some(Action::ApplyLspWorkspaceEdit {
                documents,
                expected_revisions,
                command: None,
                label,
            }) if documents.len() == 1
                && documents[0].uri.contains("caf%C3%A9%20%231.rs")
                && expected_revisions == vec![(documents[0].uri.clone(), revision)]
                && label == "format document"
        ));
        assert!(editor.pending_lsp_edit_requests.is_empty());
    }

