        assert_eq!(editor.waiting_command.as_deref(), Some("Space h"));

        editor.keymap_hint_deadline = Some(Instant::now() - Duration::from_millis(1));
        editor
            .service_background(&mut buffer, &mut runtime)
            .await
            .unwrap();

